/// Distinguishes keyboard events generated by Meya itself from physical keys.
/// Live draft updates use synthetic backspace/Unicode events; treating those as
/// an Fn chord would incorrectly cancel recording while Fn is still held.
private let meyaInjectedEventTag: Int64 = 0x4D455941

private func markAsMeyaInjected(_ event: CGEvent?) {
    event?.setIntegerValueField(.eventSourceUserData, value: meyaInjectedEventTag)
}

private extension Data {
    mutating func appendLittleEndian<T: FixedWidthInteger>(_ value: T) {
        var littleEndian = value.littleEndian
        Swift.withUnsafeBytes(of: &littleEndian) { bytes in
            append(contentsOf: bytes)
        }
    }
}

private enum WaveFile {
    static func write(samples: [Float], to url: URL, sampleRate: UInt32 = 16_000) throws {
        try FileManager.default.createDirectory(
            at: url.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )

        let pcm = samples.map { sample -> Int16 in
            let clipped = max(-1.0, min(1.0, sample))
            return Int16(clipped * 32_767.0).littleEndian
        }
        let dataSize = UInt32(pcm.count * MemoryLayout<Int16>.size)

        var data = Data()
        data.append(contentsOf: "RIFF".utf8)
        data.appendLittleEndian(UInt32(36) + dataSize)
        data.append(contentsOf: "WAVE".utf8)
        data.append(contentsOf: "fmt ".utf8)
        data.appendLittleEndian(UInt32(16))
        data.appendLittleEndian(UInt16(1))
        data.appendLittleEndian(UInt16(1))
        data.appendLittleEndian(sampleRate)
        data.appendLittleEndian(sampleRate * 2)
        data.appendLittleEndian(UInt16(2))
        data.appendLittleEndian(UInt16(16))
        data.append(contentsOf: "data".utf8)
        data.appendLittleEndian(dataSize)
        pcm.withUnsafeBytes { data.append(contentsOf: $0) }
        try data.write(to: url, options: .atomic)
    }
}

private final class AudioCapture {
    private let engine = AVAudioEngine()
    private let lock = NSLock()
    private var converter: AVAudioConverter?
    private var recordedSamples: [Float] = []
    private var tapInstalled = false

    var onLevels: (([Float]) -> Void)?

    var sampleCount: Int {
        lock.lock()
        defer { lock.unlock() }
        return recordedSamples.count
    }

    func start() throws {
        stopEngineOnly()
        lock.lock()
        recordedSamples.removeAll(keepingCapacity: true)
        lock.unlock()

        let input = engine.inputNode
        let inputFormat = input.outputFormat(forBus: 0)
        guard inputFormat.sampleRate > 0,
              let outputFormat = AVAudioFormat(
                commonFormat: .pcmFormatFloat32,
                sampleRate: 16_000,
                channels: 1,
                interleaved: false
              ),
              let converter = AVAudioConverter(from: inputFormat, to: outputFormat)
        else {
            throw NSError(
                domain: "LocalVoiceInput.Audio",
                code: 1,
                userInfo: [NSLocalizedDescriptionKey: "无法初始化麦克风音频格式"]
            )
        }
        self.converter = converter

        input.installTap(onBus: 0, bufferSize: 2_048, format: inputFormat) { [weak self] buffer, _ in
            self?.consume(buffer, outputFormat: outputFormat)
        }
        tapInstalled = true
        engine.prepare()
        try engine.start()
    }

    func snapshot() -> [Float] {
        lock.lock()
        defer { lock.unlock() }
        return recordedSamples
    }

    func snapshotWindow(from startSeconds: Double, sampleRate: Double = 16_000) -> [Float] {
        let startIndex = max(0, Int((startSeconds * sampleRate).rounded()))
        lock.lock()
        defer { lock.unlock() }
        guard startIndex < recordedSamples.count else { return [] }
        return Array(recordedSamples[startIndex...])
    }

    func stop() -> [Float] {
        stopEngineOnly()
        return snapshot()
    }

    private func stopEngineOnly() {
        if tapInstalled {
            engine.inputNode.removeTap(onBus: 0)
            tapInstalled = false
        }
        if engine.isRunning {
            engine.stop()
        }
        converter = nil
    }

    private func consume(_ inputBuffer: AVAudioPCMBuffer, outputFormat: AVAudioFormat) {
        guard let converter else { return }
        let ratio = outputFormat.sampleRate / inputBuffer.format.sampleRate
        let capacity = max(1, AVAudioFrameCount(Double(inputBuffer.frameLength) * ratio) + 8)
        guard let outputBuffer = AVAudioPCMBuffer(pcmFormat: outputFormat, frameCapacity: capacity) else {
            return
        }

        var suppliedInput = false
        var conversionError: NSError?
        let status = converter.convert(to: outputBuffer, error: &conversionError) { _, outputStatus in
            if suppliedInput {
                outputStatus.pointee = .noDataNow
                return nil
            }
            suppliedInput = true
            outputStatus.pointee = .haveData
            return inputBuffer
        }
        guard status != .error,
              conversionError == nil,
              outputBuffer.frameLength > 0,
              let channel = outputBuffer.floatChannelData?[0]
        else {
            return
        }

        let values = Array(UnsafeBufferPointer(start: channel, count: Int(outputBuffer.frameLength)))
        let levels = makeMeterLevels(from: values, barCount: 12)
        let levelCallback = onLevels
        DispatchQueue.main.async {
            levelCallback?(levels)
        }
        lock.lock()
        recordedSamples.append(contentsOf: values)
        lock.unlock()
    }

    private func makeMeterLevels(from samples: [Float], barCount: Int) -> [Float] {
        guard !samples.isEmpty else { return Array(repeating: 0, count: barCount) }
        let chunkSize = max(1, samples.count / barCount)
        return (0..<barCount).map { index in
            let start = min(samples.count, index * chunkSize)
            let end = index == barCount - 1
                ? samples.count
                : min(samples.count, start + chunkSize)
            guard start < end else { return 0 }
            let sumSquares = samples[start..<end].reduce(Float.zero) { partial, value in
                partial + value * value
            }
            let rms = sqrt(sumSquares / Float(end - start))
            let decibels = 20 * log10(max(rms, 0.000_01))
            return max(0, min(1, (decibels + 55) / 45))
        }
    }
}

private enum MeyaBrand {
    static func statusImage(accessibilityDescription: String) -> NSImage? {
        let image: NSImage?
        if let url = Bundle.main.url(forResource: "MeyaStatus-v5", withExtension: "pdf") {
            image = NSImage(contentsOf: url)
        } else {
            image = NSImage(systemSymbolName: "leaf.fill", accessibilityDescription: accessibilityDescription)
        }
        image?.size = NSSize(width: 22, height: 22)
        image?.isTemplate = true
        image?.accessibilityDescription = accessibilityDescription
        return image
    }
}

private final class MeyaMascotMeterView: NSView {
    private enum State {
        case listening
        case processing
        case complete
    }

    private var state: State = .listening
    private var leftLevel = CGFloat(0.08)
    private var rightLevel = CGFloat(0.08)
    private var coreLevel = CGFloat(0.08)
    private var animationTimer: Timer?
    private var phase = CGFloat(0)

    func update(levels newLevels: [Float]) {
        guard !newLevels.isEmpty else { return }
        let normalized = newLevels.map { CGFloat(max(0.03, min(1, $0))) }
        let midpoint = max(1, normalized.count / 2)
        let leftSamples = normalized.prefix(midpoint)
        let rightSamples = normalized.suffix(from: min(midpoint, normalized.count))
        let leftTarget = leftSamples.reduce(0, +) / CGFloat(max(1, leftSamples.count))
        let rightTarget = rightSamples.reduce(0, +) / CGFloat(max(1, rightSamples.count))
        let peak = normalized.max() ?? 0.08
        leftLevel = leftLevel * 0.58 + leftTarget * 0.42
        rightLevel = rightLevel * 0.58 + rightTarget * 0.42
        coreLevel = coreLevel * 0.52 + peak * 0.48
        needsDisplay = true
    }

    func reset() {
        stopAnimation()
        state = .listening
        leftLevel = 0.08
        rightLevel = 0.08
        coreLevel = 0.08
        needsDisplay = true
    }

    func startProcessing() {
        stopAnimation()
        state = .processing
        phase = 0
        animationTimer = Timer.scheduledTimer(withTimeInterval: 1.0 / 24.0, repeats: true) { [weak self] _ in
            guard let self else { return }
            self.phase += 0.12
            let wave = CGFloat(0.5) + CGFloat(0.5) * sin(self.phase)
            self.leftLevel = 0.18 + wave * 0.16
            self.rightLevel = 0.18 + (1 - wave) * 0.16
            self.coreLevel = 0.32
            self.needsDisplay = true
        }
    }

    func showComplete() {
        stopAnimation()
        state = .complete
        leftLevel = 0.12
        rightLevel = 0.12
        coreLevel = 0.18
        needsDisplay = true
    }

    func stopAnimation() {
        animationTimer?.invalidate()
        animationTimer = nil
    }

    override func draw(_ dirtyRect: NSRect) {
        super.draw(dirtyRect)
        let centerX = bounds.midX
        let baseline = bounds.minY + 1
        let bodyRect = NSRect(x: centerX - 13, y: baseline, width: 26, height: 16)

        func leaf(mirrored: Bool, activity: CGFloat) -> NSBezierPath {
            let direction: CGFloat = mirrored ? 1 : -1
            let lift = min(4.5, activity * 5.5)
            let path = NSBezierPath()
            path.move(to: NSPoint(x: centerX + direction * 3, y: baseline + 14))
            path.curve(
                to: NSPoint(x: centerX + direction * (11 + lift), y: baseline + 18 + lift * 0.65),
                controlPoint1: NSPoint(x: centerX + direction * 6, y: baseline + 16 + lift * 0.7),
                controlPoint2: NSPoint(x: centerX + direction * 10, y: baseline + 20 + lift * 0.65)
            )
            path.curve(
                to: NSPoint(x: centerX + direction * 3, y: baseline + 14),
                controlPoint1: NSPoint(x: centerX + direction * (17 + lift), y: baseline + 15 + lift * 0.65),
                controlPoint2: NSPoint(x: centerX + direction * 9, y: baseline + 12.5)
            )
            path.close()
            return path
        }

        let mint = NSColor(calibratedRed: 0.38, green: 0.94, blue: 0.78, alpha: 0.96)
        mint.setFill()
        leaf(mirrored: false, activity: leftLevel).fill()
        leaf(mirrored: true, activity: rightLevel).fill()
        NSBezierPath(roundedRect: bodyRect, xRadius: 9, yRadius: 9).fill()

        let faceColor = NSColor(calibratedRed: 0.025, green: 0.09, blue: 0.17, alpha: 0.92)
        faceColor.setFill()
        if state == .complete {
            faceColor.setStroke()
            for offset in [-5.0, 5.0] {
                let eye = NSBezierPath()
                eye.move(to: NSPoint(x: centerX + CGFloat(offset) - 1.8, y: baseline + 9.5))
                eye.curve(
                    to: NSPoint(x: centerX + CGFloat(offset) + 1.8, y: baseline + 9.5),
                    controlPoint1: NSPoint(x: centerX + CGFloat(offset) - 0.8, y: baseline + 8.2),
                    controlPoint2: NSPoint(x: centerX + CGFloat(offset) + 0.8, y: baseline + 8.2)
                )
                eye.lineWidth = 1.2
                eye.lineCapStyle = .round
                eye.stroke()
            }
        } else {
            NSBezierPath(ovalIn: NSRect(x: centerX - 6.5, y: baseline + 8, width: 2.5, height: 3.2)).fill()
            NSBezierPath(ovalIn: NSRect(x: centerX + 4, y: baseline + 8, width: 2.5, height: 3.2)).fill()
        }

        let coreRect = NSRect(x: centerX - 4, y: baseline + 1.5, width: 8, height: 8)
        faceColor.setFill()
        NSBezierPath(ovalIn: coreRect).fill()
        let apricot = NSColor(calibratedRed: 1.0, green: 0.69, blue: 0.34, alpha: 1)
        apricot.setStroke()
        apricot.setFill()

        if state == .complete {
            let check = NSBezierPath()
            check.move(to: NSPoint(x: centerX - 2.2, y: baseline + 5.8))
            check.line(to: NSPoint(x: centerX - 0.4, y: baseline + 4.2))
            check.line(to: NSPoint(x: centerX + 2.4, y: baseline + 7.2))
            check.lineWidth = 1.4
            check.lineCapStyle = .round
            check.lineJoinStyle = .round
            check.stroke()
        } else {
            let width = 3 + coreLevel * 5
            let waveform = NSBezierPath()
            waveform.move(to: NSPoint(x: centerX - width / 2, y: baseline + 5.5))
            waveform.curve(
                to: NSPoint(x: centerX + width / 2, y: baseline + 5.5),
                controlPoint1: NSPoint(x: centerX - width / 4, y: baseline + 5.5 + coreLevel * 3),
                controlPoint2: NSPoint(x: centerX + width / 4, y: baseline + 5.5 - coreLevel * 3)
            )
            waveform.lineWidth = 1.5
            waveform.lineCapStyle = .round
            waveform.stroke()
        }

        if state == .processing {
            NSColor(calibratedRed: 0.32, green: 0.9, blue: 1.0, alpha: 0.9).setStroke()
            let ring = NSBezierPath()
            ring.appendArc(
                withCenter: NSPoint(x: centerX, y: baseline + 5.5),
                radius: 5.6,
                startAngle: phase * 57.2958,
                endAngle: phase * 57.2958 + 210
            )
            ring.lineWidth = 1.3
            ring.lineCapStyle = .round
            ring.stroke()
        }
    }
}

private final class Maya3DAvatarView: NSView {
    private enum State {
        case listening
        case processing
        case complete
    }

    private let mascotImage: NSImage? = {
        if let named = NSImage(named: "MayaMascot3D") { return named }
        if let url = Bundle.main.url(forResource: "MayaMascot3D", withExtension: "png") {
            return NSImage(contentsOf: url)
        }
        return nil
    }()
    private var state: State = .listening
    private var leftLevel = CGFloat(0.06)
    private var rightLevel = CGFloat(0.06)
    private var coreLevel = CGFloat(0.06)
    private var phase = CGFloat(0)
    private var animationTimer: Timer?

    func update(levels: [Float]) {
        guard !levels.isEmpty else { return }
        let normalized = levels.map { CGFloat(max(0.03, min(1, $0))) }
        let midpoint = max(1, normalized.count / 2)
        let leftSamples = normalized.prefix(midpoint)
        let rightSamples = normalized.suffix(from: min(midpoint, normalized.count))
        let leftTarget = leftSamples.reduce(0, +) / CGFloat(max(1, leftSamples.count))
        let rightTarget = rightSamples.reduce(0, +) / CGFloat(max(1, rightSamples.count))
        leftLevel = leftLevel * 0.58 + leftTarget * 0.42
        rightLevel = rightLevel * 0.58 + rightTarget * 0.42
        coreLevel = coreLevel * 0.50 + (normalized.max() ?? 0.06) * 0.50
        phase += 0.18
        needsDisplay = true
    }

    func reset() {
        stopAnimation()
        state = .listening
        leftLevel = 0.06
        rightLevel = 0.06
        coreLevel = 0.06
        phase = 0
        needsDisplay = true
    }

    func startProcessing() {
        stopAnimation()
        state = .processing
        phase = 0
        animationTimer = Timer.scheduledTimer(withTimeInterval: 1.0 / 30.0, repeats: true) { [weak self] _ in
            guard let self else { return }
            self.phase += 0.09
            let wave = 0.5 + 0.5 * sin(self.phase * 1.4)
            self.leftLevel = 0.08 + 0.05 * wave
            self.rightLevel = 0.08 + 0.05 * (1 - wave)
            self.coreLevel = 0.10
            self.needsDisplay = true
        }
    }

    func showComplete() {
        stopAnimation()
        state = .complete
        leftLevel = 0.04
        rightLevel = 0.04
        coreLevel = 0.05
        needsDisplay = true
    }

    func stopAnimation() {
        animationTimer?.invalidate()
        animationTimer = nil
    }

    func renderPreview(to url: URL) throws {
        frame = NSRect(x: 0, y: 0, width: 180, height: 180)
        layoutSubtreeIfNeeded()
        guard let bitmap = bitmapImageRepForCachingDisplay(in: bounds) else {
            throw NSError(domain: "MeyaPreview", code: 1)
        }
        cacheDisplay(in: bounds, to: bitmap)
        guard let data = bitmap.representation(using: .png, properties: [:]) else {
            throw NSError(domain: "MeyaPreview", code: 2)
        }
        try data.write(to: url, options: .atomic)
    }

    override func draw(_ dirtyRect: NSRect) {
        super.draw(dirtyRect)
        guard let mascotImage else { return }
        let size = max(24, min(bounds.width, bounds.height) - 2)
        let mascotRect = NSRect(
            x: bounds.midX - size / 2,
            y: bounds.midY - size / 2,
            width: size,
            height: size
        )

        func point(_ x: CGFloat, _ y: CGFloat) -> NSPoint {
            NSPoint(x: mascotRect.minX + x * size, y: mascotRect.minY + y * size)
        }

        func drawImage() {
            mascotImage.draw(
                in: mascotRect,
                from: .zero,
                operation: .sourceOver,
                fraction: 1,
                respectFlipped: true,
                hints: [.interpolation: NSImageInterpolation.high]
            )
        }

        // The transparent 3D artwork is split at draw time. Each leaf-ear rotates
        // around its root, then the body is painted over the roots for a clean join.
        func drawEar(rect: NSRect, root: NSPoint, angle: CGFloat) {
            NSGraphicsContext.saveGraphicsState()
            let transform = NSAffineTransform()
            transform.translateX(by: root.x, yBy: root.y)
            transform.rotate(byDegrees: angle)
            transform.translateX(by: -root.x, yBy: -root.y)
            transform.concat()
            NSBezierPath(rect: rect).addClip()
            drawImage()
            NSGraphicsContext.restoreGraphicsState()
        }

        let listeningMotion = state == .listening ? CGFloat(1) : CGFloat(0.22)
        let flutter = sin(phase) * 1.2 * listeningMotion
        drawEar(
            rect: NSRect(x: mascotRect.minX + size * 0.025, y: mascotRect.minY + size * 0.625, width: size * 0.455, height: size * 0.36),
            root: point(0.455, 0.635),
            angle: (2.0 + leftLevel * 13.0) * listeningMotion + flutter
        )
        drawEar(
            rect: NSRect(x: mascotRect.minX + size * 0.52, y: mascotRect.minY + size * 0.625, width: size * 0.455, height: size * 0.36),
            root: point(0.555, 0.635),
            angle: -(2.0 + rightLevel * 13.0) * listeningMotion - flutter
        )

        let body = NSBezierPath()
        body.move(to: point(0.50, 0.055))
        body.curve(to: point(0.175, 0.27), controlPoint1: point(0.31, 0.055), controlPoint2: point(0.17, 0.12))
        body.curve(to: point(0.50, 0.665), controlPoint1: point(0.16, 0.49), controlPoint2: point(0.31, 0.665))
        body.curve(to: point(0.825, 0.27), controlPoint1: point(0.69, 0.665), controlPoint2: point(0.84, 0.49))
        body.curve(to: point(0.50, 0.055), controlPoint1: point(0.83, 0.12), controlPoint2: point(0.69, 0.055))
        body.close()
        NSGraphicsContext.saveGraphicsState()
        body.addClip()
        drawImage()
        NSGraphicsContext.restoreGraphicsState()

        // Replace the baked mouth mark with the live audio core.
        let coreCenter = point(0.50, 0.305)
        let coreRadius = size * 0.105
        let coreRect = NSRect(
            x: coreCenter.x - coreRadius,
            y: coreCenter.y - coreRadius,
            width: coreRadius * 2,
            height: coreRadius * 2
        )
        NSColor(calibratedRed: 0.018, green: 0.075, blue: 0.145, alpha: 0.98).setFill()
        NSBezierPath(ovalIn: coreRect).fill()
        NSColor(calibratedRed: 0.28, green: 0.93, blue: 0.81, alpha: 0.78).setStroke()
        let coreRing = NSBezierPath(ovalIn: coreRect.insetBy(dx: 0.7, dy: 0.7))
        coreRing.lineWidth = max(1, size * 0.012)
        coreRing.stroke()

        let apricot = NSColor(calibratedRed: 1.0, green: 0.70, blue: 0.34, alpha: 1)
        apricot.setStroke()
        apricot.setFill()
        if state == .complete {
            let check = NSBezierPath()
            check.move(to: NSPoint(x: coreCenter.x - coreRadius * 0.46, y: coreCenter.y))
            check.line(to: NSPoint(x: coreCenter.x - coreRadius * 0.10, y: coreCenter.y - coreRadius * 0.32))
            check.line(to: NSPoint(x: coreCenter.x + coreRadius * 0.52, y: coreCenter.y + coreRadius * 0.40))
            check.lineWidth = max(2, size * 0.035)
            check.lineCapStyle = .round
            check.lineJoinStyle = .round
            check.stroke()
        } else if state == .processing {
            for index in -1...1 {
                let bounce = 0.72 + 0.28 * sin(phase * 2 + CGFloat(index) * 1.4)
                let dotRadius = size * 0.014 * bounce
                NSBezierPath(ovalIn: NSRect(
                    x: coreCenter.x + CGFloat(index) * coreRadius * 0.43 - dotRadius,
                    y: coreCenter.y - dotRadius,
                    width: dotRadius * 2,
                    height: dotRadius * 2
                )).fill()
            }
        } else {
            let wave = NSBezierPath()
            let halfWidth = coreRadius * 0.62
            let amplitude = coreRadius * (0.16 + min(1, coreLevel) * 0.50)
            for index in 0...6 {
                let progress = CGFloat(index) / 6
                let x = coreCenter.x - halfWidth + progress * halfWidth * 2
                let shape = sin((progress * 3 + phase * 0.55) * .pi)
                let envelope = 1 - abs(progress - 0.5) * 1.25
                let y = coreCenter.y + shape * amplitude * max(0.28, envelope)
                if index == 0 { wave.move(to: NSPoint(x: x, y: y)) }
                else { wave.line(to: NSPoint(x: x, y: y)) }
            }
            wave.lineWidth = max(1.8, size * 0.027)
            wave.lineCapStyle = .round
            wave.lineJoinStyle = .round
            wave.stroke()
        }
    }
}

