private enum FocusedInputScreenLocator {
    private static var lastClickDisplayID: CGDirectDisplayID?
    private static var lastClickTime: TimeInterval = 0

    static func noteGlobalClick() {
        let mouse = NSEvent.mouseLocation
        guard let screen = NSScreen.screens.first(where: { $0.frame.contains(mouse) }),
              let displayID = displayID(of: screen)
        else { return }
        lastClickDisplayID = displayID
        lastClickTime = Date.timeIntervalSinceReferenceDate
    }

    static func resolve() -> NSScreen? {
        // A click is the strongest evidence for an input field: some Electron
        // controls report a zero or stale AX caret rectangle on another display.
        if Date.timeIntervalSinceReferenceDate - lastClickTime < 30,
           let displayID = lastClickDisplayID,
           let screen = screen(withDisplayID: displayID) {
            writeDiagnostic(screen: screen, reason: "recent_global_click", axRect: nil)
            return screen
        }

        if AXIsProcessTrusted(), let element = focusedElement() {
            if let caretBounds = selectedTextBounds(of: element),
               isUsableCaretRect(caretBounds),
               let screen = screen(containingAXRect: caretBounds) {
                writeDiagnostic(screen: screen, reason: "focused_caret", axRect: caretBounds)
                return screen
            }
            if let elementBounds = bounds(of: element),
               isUsableElementRect(elementBounds),
               let screen = screen(containingAXRect: elementBounds) {
                writeDiagnostic(screen: screen, reason: "focused_element", axRect: elementBounds)
                return screen
            }
        }

        if let windowBounds = frontmostWindowBounds(),
           isUsableElementRect(windowBounds),
           let screen = screen(containingAXRect: windowBounds) {
            writeDiagnostic(screen: screen, reason: "frontmost_window", axRect: windowBounds)
            return screen
        }

        let mouse = NSEvent.mouseLocation
        let screen = NSScreen.screens.first(where: { $0.frame.contains(mouse) })
            ?? NSScreen.main
            ?? NSScreen.screens.first
        if let screen {
            writeDiagnostic(screen: screen, reason: "current_mouse_fallback", axRect: nil)
        }
        return screen
    }

    private static func focusedElement() -> AXUIElement? {
        let systemWide = AXUIElementCreateSystemWide()
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            systemWide,
            kAXFocusedUIElementAttribute as CFString,
            &value
        ) == .success,
              let value
        else { return nil }
        return (value as! AXUIElement)
    }

    private static func selectedTextBounds(of element: AXUIElement) -> CGRect? {
        var rangeValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            element,
            kAXSelectedTextRangeAttribute as CFString,
            &rangeValue
        ) == .success,
              let rangeValue,
              CFGetTypeID(rangeValue) == AXValueGetTypeID()
        else { return nil }

        var range = CFRange()
        guard AXValueGetValue(rangeValue as! AXValue, .cfRange, &range),
              let parameter = AXValueCreate(.cfRange, &range)
        else { return nil }

        var boundsValue: CFTypeRef?
        guard AXUIElementCopyParameterizedAttributeValue(
            element,
            kAXBoundsForRangeParameterizedAttribute as CFString,
            parameter,
            &boundsValue
        ) == .success,
              let boundsValue,
              CFGetTypeID(boundsValue) == AXValueGetTypeID()
        else { return nil }

        var rect = CGRect.zero
        guard AXValueGetValue(boundsValue as! AXValue, .cgRect, &rect) else { return nil }
        return rect
    }

    private static func bounds(of element: AXUIElement) -> CGRect? {
        var positionValue: CFTypeRef?
        var sizeValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            element,
            kAXPositionAttribute as CFString,
            &positionValue
        ) == .success,
              AXUIElementCopyAttributeValue(
                element,
                kAXSizeAttribute as CFString,
                &sizeValue
              ) == .success,
              let positionValue,
              let sizeValue,
              CFGetTypeID(positionValue) == AXValueGetTypeID(),
              CFGetTypeID(sizeValue) == AXValueGetTypeID()
        else { return nil }

        var origin = CGPoint.zero
        var size = CGSize.zero
        guard AXValueGetValue(positionValue as! AXValue, .cgPoint, &origin),
              AXValueGetValue(sizeValue as! AXValue, .cgSize, &size)
        else { return nil }
        return CGRect(origin: origin, size: size)
    }

    private static func frontmostWindowBounds() -> CGRect? {
        guard let application = NSWorkspace.shared.frontmostApplication else { return nil }
        let appElement = AXUIElementCreateApplication(application.processIdentifier)
        var windowValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            appElement,
            kAXFocusedWindowAttribute as CFString,
            &windowValue
        ) == .success,
              let windowValue
        else { return nil }
        return bounds(of: windowValue as! AXUIElement)
    }

    private static func screen(containingAXRect rect: CGRect) -> NSScreen? {
        let center = CGPoint(x: rect.midX, y: rect.midY)
        let screens = NSScreen.screens.compactMap { screen -> (NSScreen, CGRect)? in
            guard let displayID = displayID(of: screen) else { return nil }
            return (screen, CGDisplayBounds(displayID))
        }
        if let exact = screens.first(where: { $0.1.contains(center) }) {
            return exact.0
        }
        guard let best = screens.max(by: { left, right in
            intersectionArea(rect, left.1) < intersectionArea(rect, right.1)
        }), intersectionArea(rect, best.1) > 0 else { return nil }
        return best.0
    }

    private static func isUsableCaretRect(_ rect: CGRect) -> Bool {
        !rect.isNull
            && !rect.isInfinite
            && rect.origin.x.isFinite
            && rect.origin.y.isFinite
            && rect.height.isFinite
            && rect.height >= 2
            && abs(rect.origin.x) < 100_000
            && abs(rect.origin.y) < 100_000
            && !(abs(rect.origin.x) < 0.5 && abs(rect.origin.y) < 0.5)
    }

    private static func isUsableElementRect(_ rect: CGRect) -> Bool {
        isUsableCaretRect(rect) && rect.width >= 2
    }

    private static func displayID(of screen: NSScreen) -> CGDirectDisplayID? {
        guard let number = screen.deviceDescription[
            NSDeviceDescriptionKey("NSScreenNumber")
        ] as? NSNumber else { return nil }
        return CGDirectDisplayID(number.uint32Value)
    }

    private static func screen(withDisplayID displayID: CGDirectDisplayID) -> NSScreen? {
        NSScreen.screens.first(where: { FocusedInputScreenLocator.displayID(of: $0) == displayID })
    }

    private static func intersectionArea(_ left: CGRect, _ right: CGRect) -> CGFloat {
        let intersection = left.intersection(right)
        guard !intersection.isNull else { return 0 }
        return intersection.width * intersection.height
    }

    private static func writeDiagnostic(screen: NSScreen, reason: String, axRect: CGRect?) {
        guard let projectPath = Bundle.main.object(
            forInfoDictionaryKey: "LocalVoiceProjectPath"
        ) as? String,
              !projectPath.isEmpty,
              let chosenID = displayID(of: screen)
        else { return }
        let rectDictionary: (CGRect) -> [String: Double] = { rect in
            [
                "x": Double(rect.origin.x),
                "y": Double(rect.origin.y),
                "width": Double(rect.width),
                "height": Double(rect.height),
            ]
        }
        let screens = NSScreen.screens.compactMap { candidate -> [String: Any]? in
            guard let displayID = displayID(of: candidate) else { return nil }
            return [
                "displayID": displayID,
                "name": candidate.localizedName,
                "appKitFrame": rectDictionary(candidate.frame),
                "quartzFrame": rectDictionary(CGDisplayBounds(displayID)),
            ]
        }
        var payload: [String: Any] = [
            "reason": reason,
            "chosenDisplayID": chosenID,
            "chosenName": screen.localizedName,
            "mouse": ["x": NSEvent.mouseLocation.x, "y": NSEvent.mouseLocation.y],
            "screens": screens,
            "updatedAt": ISO8601DateFormatter().string(from: Date()),
        ]
        if let axRect { payload["axRect"] = rectDictionary(axRect) }
        let file = URL(fileURLWithPath: projectPath, isDirectory: true)
            .appendingPathComponent("runtime/overlay-screen.json")
        try? FileManager.default.createDirectory(
            at: file.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )
        if let data = try? JSONSerialization.data(
            withJSONObject: payload,
            options: [.prettyPrinted, .sortedKeys]
        ) {
            try? data.write(to: file, options: .atomic)
        }
    }
}

private final class OverlayController {
    private let panel: NSPanel
    private let statusLabel = NSTextField(labelWithString: "")
    private let textLabel = NSTextField(wrappingLabelWithString: "")
    private let meterContainer = NSView()
    private let meterView = Maya3DAvatarView()
    private var meterHeightConstraint: NSLayoutConstraint!
    private var hasPositionedPanel = false
    private var placementScreen: NSScreen?

    init() {
        panel = NSPanel(
            contentRect: NSRect(x: 0, y: 0, width: 126, height: 98),
            styleMask: [.borderless, .nonactivatingPanel],
            backing: .buffered,
            defer: false
        )
        panel.level = .statusBar
        panel.isOpaque = false
        panel.backgroundColor = .clear
        panel.hasShadow = true
        panel.ignoresMouseEvents = false
        panel.isMovableByWindowBackground = true
        panel.hidesOnDeactivate = false
        panel.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]

        let background = DraggableContainerView()
        background.wantsLayer = true
        background.showsBackdrop = false

        statusLabel.font = .systemFont(ofSize: 10.5, weight: .semibold)
        statusLabel.textColor = .white
        statusLabel.alignment = .center
        statusLabel.translatesAutoresizingMaskIntoConstraints = false
        let statusShadow = NSShadow()
        statusShadow.shadowColor = NSColor(calibratedWhite: 0, alpha: 0.82)
        statusShadow.shadowBlurRadius = 3
        statusShadow.shadowOffset = NSSize(width: 0, height: -1)
        statusLabel.shadow = statusShadow

        textLabel.font = .systemFont(ofSize: 13, weight: .regular)
        textLabel.textColor = .labelColor
        textLabel.alignment = .center
        textLabel.maximumNumberOfLines = 2
        textLabel.lineBreakMode = .byTruncatingTail
        textLabel.translatesAutoresizingMaskIntoConstraints = false

        meterContainer.translatesAutoresizingMaskIntoConstraints = false
        meterView.translatesAutoresizingMaskIntoConstraints = false
        meterContainer.addSubview(meterView)

        background.addSubview(statusLabel)
        background.addSubview(meterContainer)
        background.addSubview(textLabel)
        panel.contentView = background

        meterHeightConstraint = meterContainer.heightAnchor.constraint(equalToConstant: 20)

        NSLayoutConstraint.activate([
            statusLabel.leadingAnchor.constraint(equalTo: background.leadingAnchor, constant: 12),
            statusLabel.trailingAnchor.constraint(equalTo: background.trailingAnchor, constant: -12),
            statusLabel.topAnchor.constraint(equalTo: background.topAnchor, constant: 8),
            meterContainer.leadingAnchor.constraint(equalTo: background.leadingAnchor, constant: 12),
            meterContainer.trailingAnchor.constraint(equalTo: background.trailingAnchor, constant: -12),
            meterContainer.topAnchor.constraint(equalTo: statusLabel.bottomAnchor, constant: 3),
            meterHeightConstraint,
            meterView.leadingAnchor.constraint(equalTo: meterContainer.leadingAnchor),
            meterView.trailingAnchor.constraint(equalTo: meterContainer.trailingAnchor),
            meterView.topAnchor.constraint(equalTo: meterContainer.topAnchor),
            meterView.bottomAnchor.constraint(equalTo: meterContainer.bottomAnchor),
            textLabel.leadingAnchor.constraint(equalTo: background.leadingAnchor, constant: 14),
            textLabel.trailingAnchor.constraint(equalTo: background.trailingAnchor, constant: -14),
            textLabel.topAnchor.constraint(equalTo: statusLabel.bottomAnchor, constant: 7),
            textLabel.bottomAnchor.constraint(lessThanOrEqualTo: background.bottomAnchor, constant: -10),
        ])
    }

    func show(status: String, text: String) {
        beginPlacementSession()
        setMeterMode(.hidden)
        (panel.contentView as? DraggableContainerView)?.showsBackdrop = true
        statusLabel.stringValue = status
        textLabel.stringValue = text
        positionPanel()
        panel.orderFrontRegardless()
    }

    func showRecording() {
        beginPlacementSession()
        setMeterMode(.levels)
        (panel.contentView as? DraggableContainerView)?.showsBackdrop = false
        meterView.reset()
        statusLabel.stringValue = "输入中 · 松开 Fn"
        textLabel.stringValue = ""
        positionPanel()
        panel.orderFrontRegardless()
    }

    func showRecognizing() {
        setMeterMode(.progress)
        (panel.contentView as? DraggableContainerView)?.showsBackdrop = false
        statusLabel.stringValue = "识别中…"
        textLabel.stringValue = ""
        positionPanel()
        panel.orderFrontRegardless()
    }

    func showResult() {
        setMeterMode(.complete)
        (panel.contentView as? DraggableContainerView)?.showsBackdrop = false
        statusLabel.stringValue = "完成"
        textLabel.stringValue = ""
        positionPanel()
        panel.orderFrontRegardless()
    }

    func update(levels: [Float]) {
        meterView.update(levels: levels)
    }

    func update(status: String? = nil, text: String? = nil) {
        if let status { statusLabel.stringValue = status }
        if let text { textLabel.stringValue = text }
    }

    func hide() {
        meterView.stopAnimation()
        panel.orderOut(nil)
        hasPositionedPanel = false
        placementScreen = nil
    }

    private enum MeterMode {
        case hidden
        case levels
        case progress
        case complete
    }

    private func setMeterMode(_ mode: MeterMode) {
        switch mode {
        case .hidden:
            meterView.isHidden = true
            meterView.stopAnimation()
            meterHeightConstraint.constant = 0
            textLabel.isHidden = false
            panel.setContentSize(NSSize(width: 390, height: 76))
        case .levels:
            meterView.isHidden = false
            meterView.stopAnimation()
            meterHeightConstraint.constant = 66
            textLabel.isHidden = true
            panel.setContentSize(NSSize(width: 126, height: 98))
        case .progress:
            meterView.isHidden = false
            meterHeightConstraint.constant = 66
            textLabel.isHidden = true
            meterView.startProcessing()
            panel.setContentSize(NSSize(width: 112, height: 98))
        case .complete:
            meterView.isHidden = false
            meterView.showComplete()
            meterHeightConstraint.constant = 66
            textLabel.isHidden = true
            panel.setContentSize(NSSize(width: 100, height: 98))
        }
    }

    private func positionPanel() {
        guard !hasPositionedPanel else { return }
        guard let screen = placementScreen ?? FocusedInputScreenLocator.resolve() else { return }
        let visible = screen.visibleFrame
        let frame = panel.frame
        panel.setFrameOrigin(NSPoint(
            x: visible.maxX - frame.width - 22,
            y: visible.minY + 38
        ))
        hasPositionedPanel = true
    }

    private func beginPlacementSession() {
        placementScreen = FocusedInputScreenLocator.resolve()
        hasPositionedPanel = false
    }
}

private enum UserDataStore {
    static var directory: URL {
        FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("Meya", isDirectory: true)
    }

    static var termsURL: URL { directory.appendingPathComponent("terms.txt") }
    static var glossaryURL: URL { directory.appendingPathComponent("glossary.tsv") }
    static var correctionsURL: URL { directory.appendingPathComponent("corrections.tsv") }
    static var modelConfigURL: URL { directory.appendingPathComponent("model-config.json") }

    static func prepare(seedDirectory: URL) {
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        migrateIfNeeded(name: "terms.txt", from: seedDirectory)
        migrateIfNeeded(name: "corrections.tsv", from: seedDirectory)
        migrateIfNeeded(name: "model-config.json", from: seedDirectory)
    }

    private static func migrateIfNeeded(name: String, from seedDirectory: URL) {
        let destination = directory.appendingPathComponent(name)
        if FileManager.default.fileExists(atPath: destination.path) {
            return
        }
        let source = seedDirectory.appendingPathComponent(name)
        guard FileManager.default.fileExists(atPath: source.path) else { return }
        try? FileManager.default.copyItem(at: source, to: destination)
    }
}

private struct GlossaryRow {
    var canonical: String
    var aliases: String
    var mistakes: String
}

private struct HotwordReport: Decodable {
    struct Summary: Decodable {
        let effectiveEntries: Int
        let partialEntries: Int
        let unknownEntries: Int
        let selectedHotwords: Int

        enum CodingKeys: String, CodingKey {
            case effectiveEntries = "effective_entries"
            case partialEntries = "partial_entries"
            case unknownEntries = "unknown_entries"
            case selectedHotwords = "selected_hotwords"
        }
    }

    struct Entry: Decodable {
        let canonical: String
        let status: String
    }

    let summary: Summary
    let entries: [Entry]
}

