    private func loadTerms() {
        if let source = try? String(contentsOf: glossaryURL, encoding: .utf8) {
            rows = parseGlossary(source)
        } else {
            rows = migrateLegacyRows()
        }
        loadHotwordReport()
        tableView.reloadData()
        statusLabel.textColor = .secondaryLabelColor
        updateStatus(summary(for: rows))
    }

    func numberOfRows(in tableView: NSTableView) -> Int {
        rows.count
    }

    func tableView(
        _ tableView: NSTableView,
        viewFor tableColumn: NSTableColumn?,
        row: Int
    ) -> NSView? {
        guard let tableColumn, rows.indices.contains(row) else { return nil }
        let cell = NSTableCellView()
        let field = NSTextField()
        field.isBordered = false
        field.drawsBackground = false
        let isStatus = tableColumn.identifier == statusColumn
        field.isEditable = !isStatus
        field.isSelectable = true
        field.font = .systemFont(ofSize: 13)
        field.delegate = isStatus ? nil : self
        field.tag = row
        field.identifier = tableColumn.identifier
        field.placeholderString = tableColumn.identifier == canonicalColumn
            ? "例如 NovaKit"
            : (tableColumn.identifier == aliasesColumn ? "例如 诺瓦套件" : "只填实际出现的错词")
        switch tableColumn.identifier {
        case canonicalColumn: field.stringValue = rows[row].canonical
        case aliasesColumn: field.stringValue = rows[row].aliases
        case mistakesColumn: field.stringValue = rows[row].mistakes
        default:
            let state = hotwordStatuses[rows[row].canonical.lowercased()] ?? "pending"
            switch state {
            case "effective":
                field.stringValue = "● 已生效"
                field.textColor = .systemGreen
            case "partial_unknown":
                field.stringValue = "◐ 部分无效"
                field.textColor = .systemOrange
            case "unknown":
                field.stringValue = "○ 需要发音"
                field.textColor = .systemRed
            default:
                field.stringValue = "— 待检测"
                field.textColor = .secondaryLabelColor
            }
        }
        field.translatesAutoresizingMaskIntoConstraints = false
        cell.addSubview(field)
        cell.textField = field
        NSLayoutConstraint.activate([
            field.leadingAnchor.constraint(equalTo: cell.leadingAnchor, constant: 6),
            field.trailingAnchor.constraint(equalTo: cell.trailingAnchor, constant: -6),
            field.centerYAnchor.constraint(equalTo: cell.centerYAnchor),
        ])
        return cell
    }

    func controlTextDidChange(_ notification: Notification) {
        guard let field = notification.object as? NSTextField,
              rows.indices.contains(field.tag)
        else { return }
        switch field.identifier {
        case canonicalColumn: rows[field.tag].canonical = field.stringValue
        case aliasesColumn: rows[field.tag].aliases = field.stringValue
        case mistakesColumn: rows[field.tag].mistakes = field.stringValue
        default: break
        }
        window.isDocumentEdited = true
        updateStatus(summary(for: normalizedRows(rows)))
    }

    @objc private func addTerm() {
        rows.append(GlossaryRow(canonical: "", aliases: "", mistakes: ""))
        tableView.reloadData()
        let row = rows.count - 1
        tableView.selectRowIndexes(IndexSet(integer: row), byExtendingSelection: false)
        tableView.scrollRowToVisible(row)
        tableView.editColumn(0, row: row, with: nil, select: true)
        window.isDocumentEdited = true
    }

    @objc private func removeTerms() {
        let selected = tableView.selectedRowIndexes
        guard !selected.isEmpty else { return }
        for row in selected.sorted(by: >) where rows.indices.contains(row) {
            rows.remove(at: row)
        }
        tableView.reloadData()
        window.isDocumentEdited = true
        updateStatus(summary(for: normalizedRows(rows)))
    }

    @objc private func importTerms() {
        let panel = NSOpenPanel()
        panel.title = "导入个人关键词库"
        panel.prompt = "导入并合并"
        panel.allowedContentTypes = ["txt", "csv", "tsv"].compactMap { UTType(filenameExtension: $0) }
        panel.allowsMultipleSelection = true
        panel.canChooseDirectories = false
        panel.beginSheetModal(for: window) { [weak self] response in
            guard response == .OK, let self else { return }
            var imported: [GlossaryRow] = []
            var failures = 0
            for url in panel.urls {
                do {
                    let data = try Data(contentsOf: url)
                    guard let source = String(data: data, encoding: .utf8) else {
                        failures += 1
                        continue
                    }
                    let structured = self.parseGlossary(source)
                    if !structured.isEmpty && source.contains("\t") {
                        imported.append(contentsOf: structured)
                    } else {
                        imported.append(contentsOf: self.normalizedTerms(from: source, splitColumns: true).map {
                            GlossaryRow(canonical: $0, aliases: "", mistakes: "")
                        })
                    }
                } catch {
                    failures += 1
                }
            }
            let merged = self.mergeRows(self.rows + imported)
            self.rows = merged
            self.tableView.reloadData()
            self.window.isDocumentEdited = true
            let suffix = failures == 0 ? "" : "，\(failures) 个文件读取失败（请使用 UTF-8）"
            self.updateStatus("已合并 \(imported.count) 个术语，\(self.summary(for: merged))\(suffix)")
        }
    }

    @objc private func saveTerms() {
        window.makeFirstResponder(nil)
        let normalized = normalizedRows(rows)
        let terms = compiledHotwords(normalized)
        let glossary = serializeGlossary(normalized)
        let header = "# 每行一个术语；保存后下一次识别立即生效\n"
        let body = terms.isEmpty ? header : header + terms.joined(separator: "\n") + "\n"
        do {
            try FileManager.default.createDirectory(at: UserDataStore.directory, withIntermediateDirectories: true)
            try Data(glossary.utf8).write(to: glossaryURL, options: .atomic)
            try Data(body.utf8).write(to: termsURL, options: .atomic)
            rows = normalized
            tableView.reloadData()
            window.isDocumentEdited = false
            window.close()
        } catch {
            statusLabel.textColor = .systemRed
            updateStatus("保存失败：\(error.localizedDescription)")
            NSSound.beep()
        }
    }

    private func parseGlossary(_ source: String) -> [GlossaryRow] {
        var parsed: [GlossaryRow] = []
        for rawLine in source.components(separatedBy: .newlines) {
            let line = rawLine.replacingOccurrences(of: "\u{feff}", with: "")
            guard !line.trimmingCharacters(in: .whitespaces).isEmpty,
                  !line.trimmingCharacters(in: .whitespaces).hasPrefix("#")
            else { continue }
            let columns = line.components(separatedBy: "\t")
            guard let canonical = columns.first else { continue }
            parsed.append(GlossaryRow(
                canonical: canonical,
                aliases: columns.count > 1 ? columns[1] : "",
                mistakes: columns.count > 2 ? columns[2] : ""
            ))
        }
        return normalizedRows(parsed)
    }

    private func migrateLegacyRows() -> [GlossaryRow] {
        let source = (try? String(contentsOf: termsURL, encoding: .utf8)) ?? ""
        let terms = normalizedTerms(from: source, splitColumns: false)
        var mistakes: [String: [String]] = [:]
        if let corrections = try? String(contentsOf: UserDataStore.correctionsURL, encoding: .utf8) {
            for line in corrections.components(separatedBy: .newlines) {
                let columns = line.components(separatedBy: "\t")
                if columns.count == 2, !columns[0].hasPrefix("#") {
                    mistakes[columns[1].lowercased(), default: []].append(columns[0])
                }
            }
        }
        return terms.map {
            GlossaryRow(
                canonical: $0,
                aliases: "",
                mistakes: mistakes[$0.lowercased(), default: []].joined(separator: "、")
            )
        }
    }

    private func normalizedRows(_ source: [GlossaryRow]) -> [GlossaryRow] {
        var output: [GlossaryRow] = []
        var seen = Set<String>()
        for row in source {
            let canonical = clean(row.canonical)
            let key = canonical.lowercased()
            guard isSpeakableTerm(canonical), seen.insert(key).inserted else { continue }
            let aliases = normalizedVariants(row.aliases).filter { $0.lowercased() != key }
            let mistakes = normalizedVariants(row.mistakes).filter { $0.lowercased() != key }
            output.append(GlossaryRow(
                canonical: canonical,
                aliases: aliases.joined(separator: "、"),
                mistakes: mistakes.joined(separator: "、")
            ))
            if output.count >= 100 { break }
        }
        return output
    }

    private func mergeRows(_ source: [GlossaryRow]) -> [GlossaryRow] {
        var merged: [GlossaryRow] = []
        var indexes: [String: Int] = [:]
        for row in normalizedRows(source) {
            let key = row.canonical.lowercased()
            if let index = indexes[key] {
                merged[index].aliases = mergeVariants(merged[index].aliases, row.aliases)
                merged[index].mistakes = mergeVariants(merged[index].mistakes, row.mistakes)
            } else {
                indexes[key] = merged.count
                merged.append(row)
            }
        }
        return Array(merged.prefix(100))
    }

    private func compiledHotwords(_ source: [GlossaryRow]) -> [String] {
        let candidates = source.map(\.canonical)
            + source.flatMap { normalizedVariants($0.aliases) }
        var result: [String] = []
        var seen = Set<String>()
        var length = 0
        for value in candidates where isSpeakableTerm(value) {
            let key = value.lowercased()
            let added = value.count + (result.isEmpty ? 0 : 1)
            guard !seen.contains(key), result.count < 100, length + added <= 1_000 else { continue }
            result.append(value)
            seen.insert(key)
            length += added
        }
        return result
    }

    private func serializeGlossary(_ source: [GlossaryRow]) -> String {
        let header = "# 标准写法\t发音/近音别名（、分隔）\t常见识别错词（、分隔）\n"
        let body = source.map { "\($0.canonical)\t\($0.aliases)\t\($0.mistakes)" }
            .joined(separator: "\n")
        return body.isEmpty ? header : header + body + "\n"
    }

    private func normalizedVariants(_ source: String) -> [String] {
        let separators = CharacterSet(charactersIn: "、,，;；")
        return deduplicated(source.components(separatedBy: separators).map(clean).filter { !$0.isEmpty })
    }

    private func mergeVariants(_ left: String, _ right: String) -> String {
        deduplicated(normalizedVariants(left) + normalizedVariants(right)).joined(separator: "、")
    }

    private func clean(_ value: String) -> String {
        value.trimmingCharacters(in: .whitespacesAndNewlines)
            .components(separatedBy: .whitespaces)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }

    private func summary(for source: [GlossaryRow]) -> String {
        let corrections = source.reduce(0) {
            $0 + normalizedVariants($1.aliases).count + normalizedVariants($1.mistakes).count
        }
        if let report = hotwordSummary {
            return "\(source.count) 个标准术语 · \(report.effectiveEntries) 个已生效 · \(report.unknownEntries + report.partialEntries) 个需要发音 · \(report.selectedHotwords) 个模型热词 · \(corrections) 条发音/兜底"
        }
        return "\(source.count) 个标准术语 · 尚未完成热词检测 · \(corrections) 条发音/兜底"
    }

    private func loadHotwordReport() {
        hotwordStatuses = [:]
        hotwordSummary = nil
        guard let data = try? Data(contentsOf: hotwordReportURL),
              let report = try? JSONDecoder().decode(HotwordReport.self, from: data)
        else { return }
        hotwordSummary = report.summary
        hotwordStatuses = Dictionary(uniqueKeysWithValues: report.entries.map {
            ($0.canonical.lowercased(), $0.status)
        })
    }

    private func normalizedTerms(from source: String, splitColumns: Bool) -> [String] {
        let ignoredHeaders: Set<String> = ["term", "terms", "keyword", "keywords", "name", "关键词", "关键字", "术语", "名称"]
        var values: [String] = []
        for rawLine in source.components(separatedBy: .newlines) {
            let line = rawLine.replacingOccurrences(of: "\u{feff}", with: "")
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !line.isEmpty, !line.hasPrefix("#") else { continue }
            let candidates: [String]
            if splitColumns {
                candidates = line.components(separatedBy: CharacterSet(charactersIn: ",\t;，；"))
            } else {
                candidates = [line]
            }
            for candidate in candidates {
                let value = candidate.trimmingCharacters(in: CharacterSet.whitespacesAndNewlines.union(CharacterSet(charactersIn: "\"'")))
                guard self.isSpeakableTerm(value),
                      ignoredHeaders.contains(value.lowercased()) == false,
                      value.range(of: "^[0-9.]+$", options: .regularExpression) == nil
                else { continue }
                values.append(value)
            }
        }
        return Array(deduplicated(values).prefix(100))
    }

    private func isSpeakableTerm(_ value: String) -> Bool {
        let compact = value.filter { !$0.isWhitespace }
        guard compact.count >= 2, compact.count <= 16 else { return false }

        let words = value.split(whereSeparator: { $0.isWhitespace })
        guard words.count <= 4 else { return false }

        let lowercased = value.lowercased()
        guard !lowercased.contains("://"),
              !lowercased.hasPrefix("www."),
              !value.hasPrefix("/"),
              !value.contains("\\"),
              !value.contains("_"),
              value.range(of: "[{}\\[\\]<>＝=]", options: .regularExpression) == nil,
              value.range(of: "[。！？!?，,；;：:]", options: .regularExpression) == nil
        else { return false }

        let isShortASCIIName = compact.count <= 2 && compact.unicodeScalars.allSatisfy {
            CharacterSet.alphanumerics.contains($0)
        }
        return !isShortASCIIName
    }

    private func deduplicated(_ terms: [String]) -> [String] {
        var seen = Set<String>()
        return terms.filter { seen.insert($0.lowercased()).inserted }
    }

    private func updateStatus(_ message: String) {
        statusLabel.stringValue = message
    }

    private func resetSaveButton() {
        saveButton.title = "保存并立即生效"
        saveButton.contentTintColor = nil
    }
}

private struct ModelConfiguration: Codable {
    var model: String?
    var previewModel: String?
    var finalModel: String?

    enum CodingKeys: String, CodingKey {
        case model
        case previewModel = "preview_model"
        case finalModel = "final_model"
    }
}

private struct ModelSelection: Equatable {
    var preview: String
    var final: String
}

private enum ModelConfigurationStore {
    static let paraformerPrefix = "paraformer:"
    static let defaultPreviewModel = "paraformer:iic/speech_paraformer-large_asr_nat-zh-cn-16k-common-vocab8404-online"
    static let defaultFinalModel = "paraformer:iic/speech_seaco_paraformer_large_asr_nat-zh-cn-16k-common-vocab8404-pytorch"
    static let previewCandidates = [
        "paraformer:iic/speech_paraformer-large_asr_nat-zh-cn-16k-common-vocab8404-online",
        "mlx-community/whisper-large-v3-turbo-4bit",
        "mlx-community/whisper-large-v3-turbo",
        "mlx-community/whisper-small-mlx",
        "mlx-community/whisper-base-mlx",
        "mlx-community/whisper-tiny",
    ]

    static func fileURL(projectDirectory: URL) -> URL {
        if FileManager.default.fileExists(atPath: UserDataStore.modelConfigURL.path) {
            return UserDataStore.modelConfigURL
        }
        return projectDirectory.appendingPathComponent("model-config.json")
    }

    static func load(projectDirectory: URL) -> ModelSelection {
        let url = fileURL(projectDirectory: projectDirectory)
        guard let data = try? Data(contentsOf: url),
              let configuration = try? JSONDecoder().decode(ModelConfiguration.self, from: data)
        else { return defaultSelection(projectDirectory: projectDirectory) }

        let legacy = normalized(configuration.model)
        let final = normalized(configuration.finalModel) ?? legacy ?? defaultFinalModel
        let preview = normalized(configuration.previewModel)
            ?? resolvePreviewModel(final: final, projectDirectory: projectDirectory)
        return ModelSelection(preview: preview, final: final)
    }

    static func save(selection: ModelSelection, projectDirectory: URL) throws {
        try FileManager.default.createDirectory(at: UserDataStore.directory, withIntermediateDirectories: true)
        let configuration = ModelConfiguration(
            model: nil,
            previewModel: selection.preview,
            finalModel: selection.final
        )
        let data = try JSONEncoder().encode(configuration)
        try data.write(to: UserDataStore.modelConfigURL, options: .atomic)
    }

    static func defaultSelection(projectDirectory: URL) -> ModelSelection {
        let cached = Set(discoveredModels(projectDirectory: projectDirectory))
        let preview = cached.contains(defaultPreviewModel) ? defaultPreviewModel : defaultFinalModel
        return ModelSelection(preview: preview, final: defaultFinalModel)
    }

    static func discoveredModels(projectDirectory: URL) -> [String] {
        let hub = projectDirectory.appendingPathComponent("models/huggingface/hub", isDirectory: true)
        let entries = (try? FileManager.default.contentsOfDirectory(
            at: hub,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles]
        )) ?? []
        let whisperModels = entries.compactMap { url -> String? in
            let name = url.lastPathComponent
            guard name.hasPrefix("models--") else { return nil }
            let parts = String(name.dropFirst("models--".count)).components(separatedBy: "--")
            guard parts.count >= 2 else { return nil }
            return parts[0] + "/" + parts.dropFirst().joined(separator: "--")
        }
        let paraformerDirectory = projectDirectory.appendingPathComponent(
            "models/paraformer",
            isDirectory: true
        )
        let paraformerEntries = (try? FileManager.default.contentsOfDirectory(
            at: paraformerDirectory,
            includingPropertiesForKeys: [.isDirectoryKey],
            options: [.skipsHiddenFiles]
        )) ?? []
        let paraformerModels = paraformerEntries.compactMap { url -> String? in
            guard FileManager.default.fileExists(atPath: url.appendingPathComponent("config.yaml").path),
                  FileManager.default.fileExists(atPath: url.appendingPathComponent("model.pt").path)
            else { return nil }
            guard let config = try? String(
                contentsOf: url.appendingPathComponent("config.yaml"),
                encoding: .utf8
            ), config.range(
                of: "(?m)^model:\\s*(?:Paraformer|ParaformerStreaming|SeacoParaformer|ContextualParaformer|EParaformer)\\s*$",
                options: .regularExpression
            ) != nil else { return nil }
            let model = url.lastPathComponent.replacingOccurrences(of: "--", with: "/")
            return paraformerPrefix + model
        }
        return Array(Set(whisperModels + paraformerModels)).sorted()
    }

    static func shortName(_ model: String) -> String {
        if model.hasPrefix(paraformerPrefix) {
            let value = String(model.dropFirst(paraformerPrefix.count))
            let name = value.hasPrefix("/") ? URL(fileURLWithPath: value).lastPathComponent : value
            if name.contains("seaco_paraformer") {
                return "Paraformer · SeACo 热词定稿"
            }
            if name.contains("streaming") || name.contains("online") {
                return "Paraformer · Streaming 实时"
            }
            return "Paraformer · \(name.replacingOccurrences(of: "funasr/", with: ""))"
        }
        if model.hasPrefix("/") {
            return URL(fileURLWithPath: model).lastPathComponent
        }
        return "Whisper · " + model.replacingOccurrences(of: "mlx-community/", with: "")
    }

    static func modelIdentifier(forLocalDirectory url: URL) -> String {
        let isParaformer = FileManager.default.fileExists(
            atPath: url.appendingPathComponent("config.yaml").path
        ) && FileManager.default.fileExists(
            atPath: url.appendingPathComponent("model.pt").path
        )
        return isParaformer ? paraformerPrefix + url.path : url.path
    }

    static func localPath(for model: String) -> String? {
        if model.hasPrefix(paraformerPrefix) {
            let value = String(model.dropFirst(paraformerPrefix.count))
            return value.hasPrefix("/") ? value : nil
        }
        return model.hasPrefix("/") ? model : nil
    }

    static func resolvePreviewModel(final: String, projectDirectory: URL) -> String {
        let cached = Set(discoveredModels(projectDirectory: projectDirectory))
        for candidate in previewCandidates where cached.contains(candidate) {
            return candidate
        }
        return final
    }

    private static func normalized(_ value: String?) -> String? {
        guard let value else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }
}

private final class ModelManagerController: NSObject, NSWindowDelegate {
    private let projectDirectory: URL
    private let onApply: (ModelSelection) -> Void
    private var window: NSWindow!
    private let previewModelPopup = NSPopUpButton()
    private let finalModelPopup = NSPopUpButton()
    private let rolesLabel = NSTextField(wrappingLabelWithString: "")
    private let statusLabel = NSTextField(labelWithString: "")

    init(projectDirectory: URL, onApply: @escaping (ModelSelection) -> Void) {
        self.projectDirectory = projectDirectory
        self.onApply = onApply
        super.init()
        buildWindow()
    }

    func show() {
        reloadModels()
        NSApp.activate(ignoringOtherApps: true)
        window.makeKeyAndOrderFront(nil)
    }

    func showRoles(preview: String, final: String, finalReady: Bool) {
        let previewName = preview.isEmpty ? "加载中…" : ModelConfigurationStore.shortName(preview)
        let finalName: String
        if final.isEmpty {
            finalName = "加载中…"
        } else if !finalReady {
            finalName = "\(ModelConfigurationStore.shortName(final))（加载中）"
        } else {
            finalName = ModelConfigurationStore.shortName(final)
        }
        rolesLabel.stringValue = "当前运行：实时识别 · \(previewName)\n当前运行：最终识别 · \(finalName)"
        statusLabel.stringValue = preview.isEmpty ? "正在加载识别服务…" : "配置已生效"
    }

    func showError(_ message: String) {
        statusLabel.stringValue = "加载失败：\(message)"
    }

    private func buildWindow() {
        window = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: 620, height: 430),
            styleMask: [.titled, .closable, .miniaturizable],
            backing: .buffered,
            defer: false
        )
        window.title = "麦芽 Meya · 模型管理"
        window.isReleasedWhenClosed = false
        window.delegate = self
        window.center()

        let content = NSView()
        window.contentView = content

        let title = NSTextField(labelWithString: "可插拔语音识别模型")
        title.font = .systemFont(ofSize: 20, weight: .semibold)
        title.translatesAutoresizingMaskIntoConstraints = false

        let explanation = NSTextField(wrappingLabelWithString: "分别选择说话过程中快速出字的模型，以及松开 Fn 后负责最终定稿的模型。支持 MLX Whisper 和 FunASR Paraformer；这里只列出本机已安装的模型，切换时不会联网。")
        explanation.textColor = .secondaryLabelColor
        explanation.translatesAutoresizingMaskIntoConstraints = false

        let previewLabel = NSTextField(labelWithString: "实时识别模型")
        previewLabel.font = .systemFont(ofSize: 13, weight: .medium)
        previewLabel.translatesAutoresizingMaskIntoConstraints = false
        previewModelPopup.translatesAutoresizingMaskIntoConstraints = false

        let previewHelp = NSTextField(wrappingLabelWithString: "长按 Fn 说话时用于快速显示文字，建议选择速度快、体积较小的模型。")
        previewHelp.textColor = .secondaryLabelColor
        previewHelp.font = .systemFont(ofSize: 12)
        previewHelp.translatesAutoresizingMaskIntoConstraints = false

        let finalLabel = NSTextField(labelWithString: "最终识别模型")
        finalLabel.font = .systemFont(ofSize: 13, weight: .medium)
        finalLabel.translatesAutoresizingMaskIntoConstraints = false
        finalModelPopup.translatesAutoresizingMaskIntoConstraints = false

        let finalHelp = NSTextField(wrappingLabelWithString: "松开 Fn 后重新整理并生成最终文字。SeACo 会将个人词库用于热词解码，并自动用本机 CT-Punc-C 补全标点。")
        finalHelp.textColor = .secondaryLabelColor
        finalHelp.font = .systemFont(ofSize: 12)
        finalHelp.translatesAutoresizingMaskIntoConstraints = false

        let chooseButton = NSButton(title: "添加本地模型目录…", target: self, action: #selector(chooseLocalModel))
        chooseButton.translatesAutoresizingMaskIntoConstraints = false
        let defaultButton = NSButton(title: "恢复推荐配置", target: self, action: #selector(restoreDefault))
        defaultButton.translatesAutoresizingMaskIntoConstraints = false
        let applyButton = NSButton(title: "应用两个模型", target: self, action: #selector(applyModels))
        applyButton.keyEquivalent = "\r"
        applyButton.translatesAutoresizingMaskIntoConstraints = false

        rolesLabel.textColor = .labelColor
        rolesLabel.font = .systemFont(ofSize: 13)
        rolesLabel.translatesAutoresizingMaskIntoConstraints = false
        statusLabel.textColor = .secondaryLabelColor
        statusLabel.translatesAutoresizingMaskIntoConstraints = false

        [title, explanation, previewLabel, previewModelPopup, previewHelp, finalLabel, finalModelPopup, finalHelp, rolesLabel, chooseButton, defaultButton, applyButton, statusLabel].forEach(content.addSubview)

        NSLayoutConstraint.activate([
            title.leadingAnchor.constraint(equalTo: content.leadingAnchor, constant: 24),
            title.trailingAnchor.constraint(equalTo: content.trailingAnchor, constant: -24),
            title.topAnchor.constraint(equalTo: content.topAnchor, constant: 22),
            explanation.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            explanation.trailingAnchor.constraint(equalTo: title.trailingAnchor),
            explanation.topAnchor.constraint(equalTo: title.bottomAnchor, constant: 8),
            previewLabel.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            previewLabel.topAnchor.constraint(equalTo: explanation.bottomAnchor, constant: 20),
            previewModelPopup.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            previewModelPopup.trailingAnchor.constraint(equalTo: title.trailingAnchor),
            previewModelPopup.topAnchor.constraint(equalTo: previewLabel.bottomAnchor, constant: 6),
            previewHelp.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            previewHelp.trailingAnchor.constraint(equalTo: title.trailingAnchor),
            previewHelp.topAnchor.constraint(equalTo: previewModelPopup.bottomAnchor, constant: 4),
            finalLabel.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            finalLabel.topAnchor.constraint(equalTo: previewHelp.bottomAnchor, constant: 14),
            finalModelPopup.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            finalModelPopup.trailingAnchor.constraint(equalTo: title.trailingAnchor),
            finalModelPopup.topAnchor.constraint(equalTo: finalLabel.bottomAnchor, constant: 6),
            finalHelp.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            finalHelp.trailingAnchor.constraint(equalTo: title.trailingAnchor),
            finalHelp.topAnchor.constraint(equalTo: finalModelPopup.bottomAnchor, constant: 4),
            rolesLabel.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            rolesLabel.trailingAnchor.constraint(equalTo: title.trailingAnchor),
            rolesLabel.topAnchor.constraint(equalTo: finalHelp.bottomAnchor, constant: 14),
            chooseButton.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            chooseButton.topAnchor.constraint(equalTo: rolesLabel.bottomAnchor, constant: 12),
            defaultButton.leadingAnchor.constraint(equalTo: title.leadingAnchor),
            defaultButton.bottomAnchor.constraint(equalTo: content.bottomAnchor, constant: -22),
            statusLabel.leadingAnchor.constraint(equalTo: defaultButton.trailingAnchor, constant: 12),
            statusLabel.centerYAnchor.constraint(equalTo: defaultButton.centerYAnchor),
            statusLabel.trailingAnchor.constraint(lessThanOrEqualTo: applyButton.leadingAnchor, constant: -10),
            applyButton.trailingAnchor.constraint(equalTo: title.trailingAnchor),
            applyButton.centerYAnchor.constraint(equalTo: defaultButton.centerYAnchor),
        ])
    }

    private func reloadModels() {
        let selection = ModelConfigurationStore.load(projectDirectory: projectDirectory)
        var models = ModelConfigurationStore.discoveredModels(projectDirectory: projectDirectory)
        for configured in [selection.preview, selection.final] where !models.contains(configured) {
            models.insert(configured, at: 0)
        }
        setModels(models, on: previewModelPopup, selected: selection.preview)
        setModels(models, on: finalModelPopup, selected: selection.final)
        statusLabel.stringValue = "选择后点击“应用两个模型”"
    }

    @objc private func chooseLocalModel() {
        let panel = NSOpenPanel()
        panel.title = "选择兼容的 Whisper 或 Paraformer 模型目录"
        panel.prompt = "选择模型"
        panel.canChooseFiles = false
        panel.canChooseDirectories = true
        panel.allowsMultipleSelection = false
        panel.beginSheetModal(for: window) { [weak self] response in
            guard response == .OK, let self, let url = panel.url else { return }
            let model = ModelConfigurationStore.modelIdentifier(forLocalDirectory: url)
            self.addModelIfNeeded(model, to: self.previewModelPopup)
            self.addModelIfNeeded(model, to: self.finalModelPopup)
            self.selectModel(model, on: self.finalModelPopup)
            self.statusLabel.stringValue = "已添加本地模型，请选择用途后应用"
        }
    }

    @objc private func restoreDefault() {
        let defaults = ModelConfigurationStore.defaultSelection(projectDirectory: projectDirectory)
        addModelIfNeeded(defaults.preview, to: previewModelPopup)
        addModelIfNeeded(defaults.final, to: finalModelPopup)
        selectModel(defaults.preview, on: previewModelPopup)
        selectModel(defaults.final, on: finalModelPopup)
        applyModels()
    }

    @objc private func applyModels() {
        guard let preview = selectedModel(from: previewModelPopup),
              let final = selectedModel(from: finalModelPopup),
              !preview.isEmpty,
              !final.isEmpty
        else {
            statusLabel.stringValue = "请分别选择实时识别模型和最终识别模型"
            NSSound.beep()
            return
        }
        for model in [preview, final] {
            if let path = ModelConfigurationStore.localPath(for: model),
               !FileManager.default.fileExists(atPath: path) {
                statusLabel.stringValue = "本地模型目录不存在：\(path)"
                NSSound.beep()
                return
            }
        }
        let selection = ModelSelection(preview: preview, final: final)
        do {
            try ModelConfigurationStore.save(selection: selection, projectDirectory: projectDirectory)
            statusLabel.stringValue = "正在重启两个识别服务…"
            onApply(selection)
        } catch {
            statusLabel.stringValue = "配置保存失败：\(error.localizedDescription)"
            NSSound.beep()
        }
    }

    private func setModels(_ models: [String], on popup: NSPopUpButton, selected: String) {
        popup.removeAllItems()
        for model in models {
            popup.addItem(withTitle: ModelConfigurationStore.shortName(model))
            popup.lastItem?.representedObject = model
            popup.lastItem?.toolTip = model
        }
        selectModel(selected, on: popup)
    }

    private func addModelIfNeeded(_ model: String, to popup: NSPopUpButton) {
        guard !popup.itemArray.contains(where: { ($0.representedObject as? String) == model }) else { return }
        popup.addItem(withTitle: ModelConfigurationStore.shortName(model))
        popup.lastItem?.representedObject = model
        popup.lastItem?.toolTip = model
    }

    private func selectedModel(from popup: NSPopUpButton) -> String? {
        popup.selectedItem?.representedObject as? String
    }

    private func selectModel(_ model: String, on popup: NSPopUpButton) {
        guard let item = popup.itemArray.first(where: { ($0.representedObject as? String) == model }) else {
            return
        }
        popup.select(item)
    }
}

private struct FeedbackCandidateResponse: Decodable {
    let canonical: String
    let observed: String
    let confirmations: Int
    let activated: Bool
}

private struct ASRResponse: Decodable {
    let id: Int?
    let event: String?
    let final: Bool?
    let text: String?
    let rawText: String?
    let error: String?
    let model: String?
    let role: String?
    let previewModel: String?
    let finalModel: String?
    let refined: Bool?
    let silence: Bool?
    let committedText: String?
    let committedEnd: Double?
    let tailText: String?
    let lastHypothesis: String?
    let revision: Int?
    let language: String?
    let acceptedUnchanged: Bool?
    let observed: [FeedbackCandidateResponse]?
    let activated: [FeedbackCandidateResponse]?

    enum CodingKeys: String, CodingKey {
        case id, event, final, text, error, model, role, refined, silence, revision, language
        case rawText = "raw_text"
        case previewModel = "preview_model"
        case finalModel = "final_model"
        case committedText = "committed_text"
        case committedEnd = "committed_end"
        case tailText = "tail_text"
        case lastHypothesis = "last_hypothesis"
        case acceptedUnchanged = "accepted_unchanged"
        case observed, activated
    }
}

private final class ASRService {
    typealias Completion = (Result<ASRResponse, Error>) -> Void

    private let projectDirectory: URL
    private let model: String
    private let role: String
    private let process = Process()
    private let inputPipe = Pipe()
    private let outputPipe = Pipe()
    private let errorPipe = Pipe()
    private let queue = DispatchQueue(label: "LocalVoiceInput.ASRService")
    private var outputBuffer = Data()
    private var nextID = 1
    private var pending: [Int: Completion] = [:]
    private var isStopping = false

    var onReady: ((String) -> Void)?
    var onFatal: ((String) -> Void)?

    init(projectDirectory: URL, model: String, role: String) {
        self.projectDirectory = projectDirectory
        self.model = model
        self.role = role
    }

    func start() throws {
        let python = projectDirectory.appendingPathComponent(".venv/bin/python")
        guard FileManager.default.isExecutableFile(atPath: python.path) else {
            throw NSError(
                domain: "LocalVoiceInput.ASR",
                code: 2,
                userInfo: [NSLocalizedDescriptionKey: "本地识别环境缺失，请在项目目录运行 ./bootstrap.sh"]
            )
        }
        process.executableURL = python
        process.arguments = ["-u", projectDirectory.appendingPathComponent("asr_daemon.py").path]
        process.currentDirectoryURL = projectDirectory
        var environment = ProcessInfo.processInfo.environment
        environment["HF_HUB_OFFLINE"] = "1"
        environment["HF_HOME"] = projectDirectory.appendingPathComponent("models/huggingface").path
        environment["HF_HUB_CACHE"] = projectDirectory.appendingPathComponent("models/huggingface/hub").path
        environment["LOCAL_VOICE_MODEL"] = model
        environment["LOCAL_VOICE_ROLE"] = role
        environment["LOCAL_VOICE_SAFE_INLINE_DRAFT"] = "1"
        environment["MEYA_USER_DATA"] = UserDataStore.directory.path
        process.environment = environment
        process.standardInput = inputPipe
        process.standardOutput = outputPipe
        process.standardError = errorPipe

        outputPipe.fileHandleForReading.readabilityHandler = { [weak self] handle in
            let data = handle.availableData
            guard !data.isEmpty else { return }
            self?.queue.async { self?.consumeOutput(data) }
        }
        errorPipe.fileHandleForReading.readabilityHandler = { handle in
            let data = handle.availableData
            if !data.isEmpty, let message = String(data: data, encoding: .utf8) {
                NSLog("ASR: %@", message.trimmingCharacters(in: .whitespacesAndNewlines))
            }
        }
        process.terminationHandler = { [weak self] process in
            guard let self else { return }
            self.failPending(NSError(
                domain: "LocalVoiceInput.ASR",
                code: 3,
                userInfo: [NSLocalizedDescriptionKey: "识别服务已退出（\(process.terminationStatus)）"]
            ))
            guard !self.isStopping, process.terminationStatus != 0 else { return }
            DispatchQueue.main.async {
                self.onFatal?("识别服务已退出（\(process.terminationStatus)）")
            }
        }
        try process.run()
    }

    func transcribe(
        audioURL: URL,
        final: Bool,
        windowStart: Double? = nil,
        committedText: String? = nil,
        committedEnd: Double? = nil,
        lastHypothesis: String? = nil,
        revision: Int? = nil,
        language: String? = nil,
        contextText: String? = nil,
        draftText: String? = nil,
        appName: String? = nil,
        appBundle: String? = nil,
        completion: @escaping Completion
    ) {
        queue.async { [weak self] in
            guard let self else { return }
            guard self.process.isRunning else {
                DispatchQueue.main.async {
                    completion(.failure(NSError(
                        domain: "LocalVoiceInput.ASR",
                        code: 4,
                        userInfo: [NSLocalizedDescriptionKey: "识别服务未运行"]
                    )))
                }
                return
            }
            let id = self.nextID
            self.nextID += 1
            self.pending[id] = completion
            var request: [String: Any] = [
                "id": id,
                "command": "transcribe",
                "audio_path": audioURL.path,
                "final": final,
            ]
            if let windowStart { request["window_start"] = windowStart }
            if let committedText { request["committed_text"] = committedText }
            if let committedEnd { request["committed_end"] = committedEnd }
            if let lastHypothesis { request["last_hypothesis"] = lastHypothesis }
            if let revision { request["revision"] = revision }
            if let language, !language.isEmpty { request["language"] = language }
            if let contextText, !contextText.isEmpty { request["context_text"] = contextText }
            if let draftText, !draftText.isEmpty { request["draft_text"] = draftText }
            if let appName, !appName.isEmpty { request["app_name"] = appName }
            if let appBundle, !appBundle.isEmpty { request["app_bundle"] = appBundle }
            do {
                var data = try JSONSerialization.data(withJSONObject: request)
                data.append(0x0A)
                try self.inputPipe.fileHandleForWriting.write(contentsOf: data)
            } catch {
                self.pending.removeValue(forKey: id)
                DispatchQueue.main.async { completion(.failure(error)) }
                return
            }
            let timeout = final ? 60.0 : 15.0
            self.queue.asyncAfter(deadline: .now() + timeout) { [weak self] in
                guard let self, let expired = self.pending.removeValue(forKey: id) else { return }
                DispatchQueue.main.async {
                    expired(.failure(NSError(
                        domain: "LocalVoiceInput.ASR",
                        code: 5,
                        userInfo: [NSLocalizedDescriptionKey: "识别超时，请重试"]
                    )))
                }
            }
        }
    }

    func submitFeedback(
        expectedText: String,
        editedText: String,
        rawText: String,
        finalText: String,
        audioPath: String,
        appName: String,
        explicit: Bool = false,
        completion: @escaping Completion
    ) {
        queue.async { [weak self] in
            guard let self else { return }
            guard self.process.isRunning else {
                DispatchQueue.main.async {
                    completion(.failure(NSError(
                        domain: "LocalVoiceInput.ASR",
                        code: 4,
                        userInfo: [NSLocalizedDescriptionKey: "学习服务未运行"]
                    )))
                }
                return
            }
            let id = self.nextID
            self.nextID += 1
            self.pending[id] = completion
            let request: [String: Any] = [
                "id": id,
                "command": "feedback",
                "expected_text": expectedText,
                "edited_text": editedText,
                "raw_text": rawText,
                "final_text": finalText,
                "audio_path": audioPath,
                "app_name": appName,
                "explicit": explicit,
            ]
            do {
                var data = try JSONSerialization.data(withJSONObject: request)
                data.append(0x0A)
                try self.inputPipe.fileHandleForWriting.write(contentsOf: data)
            } catch {
                self.pending.removeValue(forKey: id)
                DispatchQueue.main.async { completion(.failure(error)) }
                return
            }
            self.queue.asyncAfter(deadline: .now() + 10) { [weak self] in
                guard let self, let expired = self.pending.removeValue(forKey: id) else { return }
                DispatchQueue.main.async {
                    expired(.failure(NSError(
                        domain: "LocalVoiceInput.ASR",
                        code: 5,
                        userInfo: [NSLocalizedDescriptionKey: "学习请求超时，请重试"]
                    )))
                }
            }
        }
    }

    private func failPending(_ error: Error) {
        queue.async {
            let completions = Array(self.pending.values)
            self.pending.removeAll()
            DispatchQueue.main.async {
                completions.forEach { $0(.failure(error)) }
            }
        }
    }

    func stop() {
        isStopping = true
        outputPipe.fileHandleForReading.readabilityHandler = nil
        errorPipe.fileHandleForReading.readabilityHandler = nil
        if process.isRunning {
            process.terminate()
        }
    }

    private func consumeOutput(_ data: Data) {
        outputBuffer.append(data)
        while let newline = outputBuffer.firstIndex(of: 0x0A) {
            let line = outputBuffer.prefix(upTo: newline)
            outputBuffer.removeSubrange(...newline)
            guard !line.isEmpty else { continue }
            do {
                let response = try JSONDecoder().decode(ASRResponse.self, from: Data(line))
                if response.event == "ready" {
                    DispatchQueue.main.async { [weak self] in
                        self?.onReady?(response.model ?? "")
                    }
                    continue
                }
                if response.event == "fatal" {
                    DispatchQueue.main.async { [weak self] in
                        self?.onFatal?(response.error ?? "未知模型错误")
                    }
                    continue
                }
                guard let id = response.id, let completion = pending.removeValue(forKey: id) else {
                    continue
                }
                DispatchQueue.main.async {
                    if let message = response.error {
                        completion(.failure(NSError(
                            domain: "LocalVoiceInput.ASR",
                            code: 1,
                            userInfo: [NSLocalizedDescriptionKey: message]
                        )))
                    } else {
                        completion(.success(response))
                    }
                }
            } catch {
                NSLog("ASR JSON 解析失败: %@", error.localizedDescription)
            }
        }
    }
}

private enum TextInserter {
    private struct PasteboardSnapshot {
        let items: [[NSPasteboard.PasteboardType: Data]]
    }

    static func insert(_ text: String) -> Bool {
        guard AXIsProcessTrusted() else {
            requestAccessibilityPermission()
            return false
        }
        if insertUsingAccessibility(text) {
            return true
        }

        let pasteboard = NSPasteboard.general
        let snapshot = snapshotPasteboard(pasteboard)
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        let insertedChangeCount = pasteboard.changeCount

        let source = CGEventSource(stateID: .combinedSessionState)
        let keyDown = CGEvent(keyboardEventSource: source, virtualKey: 9, keyDown: true)
        let keyUp = CGEvent(keyboardEventSource: source, virtualKey: 9, keyDown: false)
        keyDown?.flags = .maskCommand
        keyUp?.flags = .maskCommand
        markAsMeyaInjected(keyDown)
        markAsMeyaInjected(keyUp)
        keyDown?.post(tap: .cghidEventTap)
        keyUp?.post(tap: .cghidEventTap)

        DispatchQueue.main.asyncAfter(deadline: .now() + 0.8) {
            guard pasteboard.changeCount == insertedChangeCount else { return }
            restorePasteboard(snapshot, to: pasteboard)
        }
        return true
    }

    private static func insertUsingAccessibility(_ text: String) -> Bool {
        let systemWide = AXUIElementCreateSystemWide()
        var focusedValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            systemWide,
            kAXFocusedUIElementAttribute as CFString,
            &focusedValue
        ) == .success,
              let focusedValue
        else { return false }

        let element = focusedValue as! AXUIElement
        var subroleValue: CFTypeRef?
        if AXUIElementCopyAttributeValue(
            element,
            kAXSubroleAttribute as CFString,
            &subroleValue
        ) == .success,
           let subrole = subroleValue as? String,
           subrole == (kAXSecureTextFieldSubrole as String) {
            return false
        }

        var settable = DarwinBoolean(false)
        guard AXUIElementIsAttributeSettable(
            element,
            kAXSelectedTextAttribute as CFString,
            &settable
        ) == .success,
              settable.boolValue
        else { return false }

        return AXUIElementSetAttributeValue(
            element,
            kAXSelectedTextAttribute as CFString,
            text as CFString
        ) == .success
    }

    static func requestAccessibilityPermission() {
        let key = kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String
        let options = [key: true] as CFDictionary
        _ = AXIsProcessTrustedWithOptions(options)
    }

    private static func snapshotPasteboard(_ pasteboard: NSPasteboard) -> PasteboardSnapshot {
        let items = (pasteboard.pasteboardItems ?? []).map { item in
            Dictionary(uniqueKeysWithValues: item.types.compactMap { type in
                item.data(forType: type).map { (type, $0) }
            })
        }
        return PasteboardSnapshot(items: items)
    }

    private static func restorePasteboard(_ snapshot: PasteboardSnapshot, to pasteboard: NSPasteboard) {
        pasteboard.clearContents()
        let items: [NSPasteboardItem] = snapshot.items.map { values in
            let item = NSPasteboardItem()
            for (type, data) in values {
                item.setData(data, forType: type)
            }
            return item
        }
        if !items.isEmpty {
            pasteboard.writeObjects(items)
        }
    }
}

private struct FeedbackSubmission {
    let observationID: UUID
    let expectedText: String
    let editedText: String
    let rawText: String
    let finalText: String
    let audioPath: String
    let appName: String
}

private final class PendingFeedbackObservation {
    let id = UUID()
    let target: AXUIElement?
    var expectedFieldText: String?
    let insertedText: String
    var rawText = ""
    var finalText = ""
    var audioPath = ""
    var appName = ""

    init(target: AXUIElement?, expectedFieldText: String?, insertedText: String) {
        self.target = target
        self.expectedFieldText = expectedFieldText
        self.insertedText = insertedText
        finalText = insertedText
    }
}

private final class LiveDraftInserter {
    private var target: AXUIElement?
    private var originalRange = CFRange(location: 0, length: 0)
    private var originalText = ""
    private var ownedRange = CFRange(location: 0, length: 0)
    private var lastDraft = ""
    private var usesAccessibilityRange = false
    private var selectionIsKnown = false
    private var frontmostPID: pid_t?
    private var initialValue: String?
    private var pendingFeedback: PendingFeedbackObservation?
    private(set) var isReady = false
    private(set) var contextText = ""

    func begin() {
        reset()
        guard AXIsProcessTrusted() else {
            writeDiagnostic(state: "unavailable_not_trusted")
            return
        }
        guard let application = NSWorkspace.shared.frontmostApplication else {
            writeDiagnostic(state: "unavailable_no_frontmost_application")
            return
        }
        frontmostPID = application.processIdentifier

        let focused = focusedElement()
        if let focused, isSecureField(focused) {
            writeDiagnostic(state: "unavailable_secure_field")
            reset()
            return
        }

        guard let focused, let selection = selectedRange(of: focused) else {
            target = focused
            isReady = true
            writeDiagnostic(state: "ready_unicode_application_fallback")
            return
        }

        let initialSelectedText: String
        if selection.length == 0 {
            initialSelectedText = ""
        } else {
            guard let value = selectedText(of: focused) else { return }
            initialSelectedText = value
        }
        target = focused
        contextText = surroundingText(of: focused, selection: selection)
        initialValue = textValue(of: focused)
        originalRange = selection
        originalText = initialSelectedText
        ownedRange = selection
        selectionIsKnown = true
        usesAccessibilityRange = supportsDraftEditing(focused)
        isReady = true
        writeDiagnostic(state: usesAccessibilityRange ? "ready_accessibility_range" : "ready_unicode_fallback")
    }

    func update(_ text: String) -> Bool {
        guard isReady, !text.isEmpty else { return false }
        return replaceDraft(with: text, finish: false)
    }

    func commit(_ text: String) -> Bool {
        guard isReady, !text.isEmpty else { return false }
        return replaceDraft(with: text, finish: true)
    }

    func prepareFeedback(finalText: String) {
        guard !finalText.isEmpty else { return }
        var expectedFieldText: String?
        if let initialValue {
            let source = initialValue as NSString
            let range = NSRange(location: originalRange.location, length: originalRange.length)
            if range.location >= 0,
               range.location + range.length <= source.length {
                let expected = source.replacingCharacters(in: range, with: finalText)
                if expected.utf16.count <= 8_000 {
                    expectedFieldText = expected
                }
            }
        }
        pendingFeedback = PendingFeedbackObservation(
            target: target,
            expectedFieldText: expectedFieldText,
            insertedText: finalText
        )
    }

    /// Capture the field after the final text has actually landed. Some
    /// Electron/contenteditable controls expose AXValue only after text is
    /// inserted, so the baseline cannot always be built in begin().
    func captureFeedbackBaseline() {
        guard let pendingFeedback,
              pendingFeedback.expectedFieldText == nil,
              let target = pendingFeedback.target,
              let currentText = textValue(of: target),
              !currentText.isEmpty,
              currentText.utf16.count <= 8_000,
              currentText.localizedCaseInsensitiveContains(pendingFeedback.insertedText)
        else { return }
        pendingFeedback.expectedFieldText = currentText
    }

    func attachRecognition(rawText: String, finalText: String, audioPath: String, appName: String) {
        guard let pendingFeedback else { return }
        pendingFeedback.rawText = rawText
        pendingFeedback.finalText = finalText
        pendingFeedback.audioPath = audioPath
        pendingFeedback.appName = appName
    }

    var hasPendingFeedback: Bool {
        pendingFeedback?.finalText.isEmpty == false
    }

    func automaticFeedbackSubmission(requireModification: Bool = false) -> FeedbackSubmission? {
        guard let pendingFeedback,
              !pendingFeedback.finalText.isEmpty,
              let target = pendingFeedback.target,
              let editedText = textValue(of: target),
              !editedText.isEmpty,
              editedText.utf16.count <= 8_000
        else { return nil }
        // If a full-field baseline was unavailable, compare the recognized
        // sentence with the currently readable composer. This is the common
        // Codex/Electron fallback path and avoids an unnecessary dialog.
        let expectedText = pendingFeedback.expectedFieldText ?? pendingFeedback.insertedText
        guard !requireModification || editedText != expectedText else { return nil }
        return feedbackSubmission(
            pendingFeedback,
            expectedText: expectedText,
            editedText: editedText
        )
    }

    func feedbackDialogTexts() -> (recognized: String, corrected: String)? {
        guard let pendingFeedback, !pendingFeedback.finalText.isEmpty else { return nil }
        let recognized = pendingFeedback.expectedFieldText ?? pendingFeedback.insertedText
        let current = pendingFeedback.target.flatMap { textValue(of: $0) }
        let corrected = current.flatMap { value in
            let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
            return trimmed.isEmpty || trimmed == recognized ? nil : value
        } ?? recognized
        return (recognized, corrected)
    }

    func manualFeedbackSubmission(originalText: String, correctedText: String) -> FeedbackSubmission? {
        let original = originalText.trimmingCharacters(in: .whitespacesAndNewlines)
        let corrected = correctedText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let pendingFeedback,
              !pendingFeedback.finalText.isEmpty,
              !original.isEmpty,
              !corrected.isEmpty,
              corrected != original,
              original.utf16.count <= 8_000,
              corrected.utf16.count <= 8_000
        else { return nil }
        return feedbackSubmission(
            pendingFeedback,
            expectedText: original,
            editedText: corrected
        )
    }

    func clearPendingFeedback(observationID: UUID) {
        guard pendingFeedback?.id == observationID else { return }
        pendingFeedback = nil
    }

    private func feedbackSubmission(
        _ pending: PendingFeedbackObservation,
        expectedText: String,
        editedText: String
    ) -> FeedbackSubmission {
        FeedbackSubmission(
            observationID: pending.id,
            expectedText: expectedText,
            editedText: editedText,
            rawText: pending.rawText,
            finalText: pending.finalText,
            audioPath: pending.audioPath,
            appName: pending.appName
        )
    }

    @discardableResult
    func cancel() -> Bool {
        if !usesAccessibilityRange {
            guard isReady, replaceUsingKeyboard(with: originalText, finish: true) else {
                reset()
                return false
            }
            return true
        }
        guard isReady, let target, targetStillFocused(target), ownsCurrentDraft(target) else {
            reset()
            return false
        }
        guard setSelectedRange(ownedRange, on: target),
              AXUIElementSetAttributeValue(
                target,
                kAXSelectedTextAttribute as CFString,
                originalText as CFString
              ) == .success
        else {
            reset()
            return false
        }
        let caret = CFRange(
            location: originalRange.location + originalText.utf16.count,
            length: 0
        )
        _ = setSelectedRange(caret, on: target)
        reset()
        return true
    }

    private func replaceDraft(with replacement: String, finish: Bool) -> Bool {
        if !usesAccessibilityRange {
            return replaceUsingKeyboard(with: replacement, finish: finish)
        }
        guard let target, targetStillFocused(target), ownsCurrentDraft(target),
              setSelectedRange(ownedRange, on: target),
              AXUIElementSetAttributeValue(
                target,
                kAXSelectedTextAttribute as CFString,
                replacement as CFString
              ) == .success
        else {
            reset()
            return false
        }
        ownedRange.length = replacement.utf16.count
        lastDraft = replacement
        let caret = CFRange(location: ownedRange.location + ownedRange.length, length: 0)
        _ = setSelectedRange(caret, on: target)
        if finish {
            reset()
        }
        return true
    }

    private func replaceUsingKeyboard(
        with replacement: String,
        finish: Bool
    ) -> Bool {
        guard frontmostApplicationIsUnchanged(), keyboardTargetIsSafe() else {
            writeDiagnostic(state: "unicode_fallback_lost_focus")
            reset()
            return false
        }
        guard postBackspaces(lastDraft.count), postUnicode(replacement) else {
            writeDiagnostic(state: "unicode_fallback_event_failed")
            reset()
            return false
        }
        ownedRange.length = replacement.utf16.count
        lastDraft = replacement
        writeDiagnostic(state: finish ? "committed_unicode_fallback" : "updated_unicode_fallback")
        if finish {
            reset()
        }
        return true
    }

    private func keyboardTargetIsSafe() -> Bool {
        if let target, let focused = focusedElement(), !CFEqual(focused, target) {
            return false
        }
        guard selectionIsKnown, !lastDraft.isEmpty, let element = target else { return true }
        guard let selection = selectedRange(of: element), selection.length == 0 else { return false }
        return selection.location == originalRange.location + lastDraft.utf16.count
    }

    private func frontmostApplicationIsUnchanged() -> Bool {
        guard let frontmostPID else { return false }
        return NSWorkspace.shared.frontmostApplication?.processIdentifier == frontmostPID
    }

    private func postBackspaces(_ count: Int) -> Bool {
        guard count > 0 else { return true }
        guard let source = CGEventSource(stateID: .combinedSessionState) else { return false }
        for _ in 0..<count {
            guard let keyDown = CGEvent(keyboardEventSource: source, virtualKey: 51, keyDown: true),
                  let keyUp = CGEvent(keyboardEventSource: source, virtualKey: 51, keyDown: false)
            else { return false }
            markAsMeyaInjected(keyDown)
            markAsMeyaInjected(keyUp)
            keyDown.post(tap: .cghidEventTap)
            keyUp.post(tap: .cghidEventTap)
        }
        return true
    }

    private func postUnicode(_ text: String) -> Bool {
        guard !text.isEmpty else { return true }
        guard let source = CGEventSource(stateID: .combinedSessionState),
              let keyDown = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: true),
              let keyUp = CGEvent(keyboardEventSource: source, virtualKey: 0, keyDown: false)
        else { return false }
        markAsMeyaInjected(keyDown)
        markAsMeyaInjected(keyUp)
        let units = Array(text.utf16)
        units.withUnsafeBufferPointer { buffer in
            guard let baseAddress = buffer.baseAddress else { return }
            keyDown.keyboardSetUnicodeString(stringLength: buffer.count, unicodeString: baseAddress)
            keyUp.keyboardSetUnicodeString(stringLength: buffer.count, unicodeString: baseAddress)
        }
        keyDown.post(tap: .cghidEventTap)
        keyUp.post(tap: .cghidEventTap)
        return true
    }

    private func ownsCurrentDraft(_ element: AXUIElement) -> Bool {
        if lastDraft.isEmpty {
            return true
        }
        guard setSelectedRange(ownedRange, on: element),
              let selected = selectedText(of: element),
              selected == lastDraft
        else { return false }
        return true
    }

    private func focusedElement() -> AXUIElement? {
        let systemWide = AXUIElementCreateSystemWide()
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            systemWide,
            kAXFocusedUIElementAttribute as CFString,
            &value
        ) == .success,
              let value
        else { return nil }
        return (value as! AXUIElement)
    }

    private func targetStillFocused(_ element: AXUIElement) -> Bool {
        guard let focused = focusedElement() else { return false }
        return CFEqual(focused, element)
    }

    private func supportsDraftEditing(_ element: AXUIElement) -> Bool {
        var textSettable = DarwinBoolean(false)
        var rangeSettable = DarwinBoolean(false)
        guard AXUIElementIsAttributeSettable(
            element,
            kAXSelectedTextAttribute as CFString,
            &textSettable
        ) == .success,
              AXUIElementIsAttributeSettable(
                element,
                kAXSelectedTextRangeAttribute as CFString,
                &rangeSettable
              ) == .success
        else { return false }
        return textSettable.boolValue && rangeSettable.boolValue
    }

    private func isSecureField(_ element: AXUIElement) -> Bool {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            element,
            kAXSubroleAttribute as CFString,
            &value
        ) == .success,
              let subrole = value as? String
        else { return false }
        return subrole == (kAXSecureTextFieldSubrole as String)
    }

    private func selectedRange(of element: AXUIElement) -> CFRange? {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            element,
            kAXSelectedTextRangeAttribute as CFString,
            &value
        ) == .success,
              let value,
              CFGetTypeID(value) == AXValueGetTypeID()
        else { return nil }
        var range = CFRange(location: 0, length: 0)
        guard AXValueGetValue(value as! AXValue, .cfRange, &range) else { return nil }
        return range
    }

    private func selectedText(of element: AXUIElement) -> String? {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            element,
            kAXSelectedTextAttribute as CFString,
            &value
        ) == .success
        else { return nil }
        return value as? String
    }

    private func textValue(of element: AXUIElement) -> String? {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            element,
            kAXValueAttribute as CFString,
            &value
        ) == .success
        else { return nil }
        return value as? String
    }

    private func surroundingText(of element: AXUIElement, selection: CFRange, limit: Int = 800) -> String {
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(
            element,
            kAXValueAttribute as CFString,
            &value
        ) == .success,
              let text = value as? String,
              !text.isEmpty
        else { return "" }
        let source = text as NSString
        let caret = min(max(0, selection.location), source.length)
        let half = max(1, limit / 2)
        let start = max(0, caret - half)
        let end = min(source.length, caret + half)
        return source.substring(with: NSRange(location: start, length: end - start))
    }

    private func setSelectedRange(_ range: CFRange, on element: AXUIElement) -> Bool {
        var mutableRange = range
        guard let value = AXValueCreate(.cfRange, &mutableRange) else { return false }
        return AXUIElementSetAttributeValue(
            element,
            kAXSelectedTextRangeAttribute as CFString,
            value
        ) == .success
    }

    private func reset() {
        target = nil
        originalRange = CFRange(location: 0, length: 0)
        originalText = ""
        ownedRange = CFRange(location: 0, length: 0)
        lastDraft = ""
        usesAccessibilityRange = false
        selectionIsKnown = false
        frontmostPID = nil
        initialValue = nil
        isReady = false
        contextText = ""
    }

    private func writeDiagnostic(state: String) {
        guard let projectPath = Bundle.main.object(forInfoDictionaryKey: "LocalVoiceProjectPath") as? String else { return }
        let file = URL(fileURLWithPath: projectPath, isDirectory: true)
            .appendingPathComponent("runtime", isDirectory: true)
            .appendingPathComponent("live-draft-status.json")
        let payload: [String: Any] = [
            "state": state,
            "draftCharacters": lastDraft.count,
            "updatedAt": ISO8601DateFormatter().string(from: Date()),
        ]
        do {
            try FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
            let data = try JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys])
            try data.write(to: file, options: .atomic)
        } catch {
            NSLog("无法写入实时草稿自检状态：%@", error.localizedDescription)
        }
    }
}

@objc(LocalVoiceInputController)
final class LocalVoiceInputController: IMKInputController {
    func commitFinalText(_ text: String) {
        let replacement = NSRange(location: NSNotFound, length: NSNotFound)
        client().insertText(text, replacementRange: replacement)
    }

    override func composedString(_ sender: Any!) -> Any! {
        NSAttributedString(string: "")
    }

    override func originalString(_ sender: Any!) -> NSAttributedString! {
        NSAttributedString(string: "")
    }

    override func commitComposition(_ sender: Any!) {}

    override func handle(_ event: NSEvent!, client sender: Any!) -> Bool {
        if event.type == .flagsChanged || event.type == .keyDown || event.type == .keyUp {
            return AppDelegate.shared?.handleInputMethodModifierEvent(event) ?? false
        }
        return false
    }

    override func recognizedEvents(_ sender: Any!) -> Int {
        Int(NSEvent.EventTypeMask.keyDown.rawValue | NSEvent.EventTypeMask.keyUp.rawValue | NSEvent.EventTypeMask.flagsChanged.rawValue)
    }

    override func activateServer(_ sender: Any!) {
        super.activateServer(sender)
        AppDelegate.shared?.activateInputController(self)
    }

    override func deactivateServer(_ sender: Any!) {
        AppDelegate.shared?.deactivateInputController(self)
        super.deactivateServer(sender)
    }

    override func inputControllerWillClose() {
        AppDelegate.shared?.deactivateInputController(self)
        super.inputControllerWillClose()
    }
}

private enum LivePreview {
    static let minPartialSamples = 16_000
    static let partialPollInterval = 0.55
    static let firstPartialDelay = 0.9
}

private enum RollingWindow {
    static let sampleRate = 16_000.0
    static let windowSeconds = 6.0
    static let overlapSeconds = 0.8
    static let fullFinalLimit = 60.0

    static func bounds(duration: Double, committedEnd: Double) -> (start: Double, end: Double) {
        guard duration > 0 else { return (0, 0) }
        let start = max(0, committedEnd - overlapSeconds, duration - windowSeconds)
        return (start, duration)
    }

    static func shouldRerunFull(duration: Double, committedEnd: Double) -> Bool {
        duration <= fullFinalLimit || duration - committedEnd > fullFinalLimit
    }
}

