        startASRServices(selection: ModelConfigurationStore.load(projectDirectory: projectDirectory))
    }

    func applicationWillTerminate(_ notification: Notification) {
        partialTimer?.invalidate()
        functionKeyHoldWorkItem?.cancel()
        functionKeyPollTimer?.invalidate()
        functionKeyPermissionTimer?.invalidate()
        _ = audioCapture.stop()
        previewService?.stop()
        refineService?.stop()
        if let functionKeyGlobalMonitor { NSEvent.removeMonitor(functionKeyGlobalMonitor) }
        if let screenMouseMonitor { NSEvent.removeMonitor(screenMouseMonitor) }
        if let functionKeyLocalMonitor { NSEvent.removeMonitor(functionKeyLocalMonitor) }
        if let functionKeyEventTapSource {
            CFRunLoopRemoveSource(CFRunLoopGetMain(), functionKeyEventTapSource, .commonModes)
        }
        if let functionKeyEventTap { CFMachPortInvalidate(functionKeyEventTap) }
    }

