    private func promptForRequiredPermissionsIfNeeded() {
        let hasInputMonitoring = CGPreflightListenEventAccess()
        let hasAccessibility = AXIsProcessTrusted()
        guard !hasInputMonitoring || !hasAccessibility else { return }

        functionKeyStatusItem?.title = "Fn 不可用：当前进程还没拿到系统权限"
        let version = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String ?? "unknown"
        let promptKey = "permissionsPromptedVersion"
        guard UserDefaults.standard.string(forKey: promptKey) != version else { return }
        UserDefaults.standard.set(version, forKey: promptKey)

        overlay.show(
            status: "请再勾选一次当前这份麦芽",
            text: "设置页勾上了也不够：系统把权限记在旧签名上，这份进程对不上。请只保留输入法目录里这一份麦芽，重新打开输入监控和辅助功能，然后菜单选「我已授权，重启麦芽」。"
        )
        openFunctionKeyPermissionSettings()
    }

    @objc private func openFunctionKeyPermissionSettings() {
        _ = CGRequestListenEventAccess()
        TextInserter.requestAccessibilityPermission()
        if let accessibilityURL = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility") {
            NSWorkspace.shared.open(accessibilityURL)
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.2) {
            if let monitoringURL = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_ListenEvent") {
                NSWorkspace.shared.open(monitoringURL)
            }
        }
    }

    @objc private func restartForFunctionKeyPermissions() {
        NSApp.terminate(nil)
    }

    private func requestMicrophonePermissionOnLaunch() {
        guard AVCaptureDevice.authorizationStatus(for: .audio) == .notDetermined else { return }
        NSApp.activate(ignoringOtherApps: true)
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) { [weak self] in
            AVCaptureDevice.requestAccess(for: .audio) { granted in
                guard !granted else { return }
                DispatchQueue.main.async {
                    self?.showPermissionError("请在“系统设置 → 隐私与安全性 → 麦克风”中允许麦芽 Meya。")
                }
            }
        }
    }

    private func setupFunctionKeyHold() {
        if screenMouseMonitor == nil {
            screenMouseMonitor = NSEvent.addGlobalMonitorForEvents(
                matching: [.leftMouseDown, .rightMouseDown]
            ) { _ in
                FocusedInputScreenLocator.noteGlobalClick()
            }
        }
        installFunctionKeyMonitorsIfNeeded()
        tryCreateFunctionKeyEventTap()
        if functionKeyPermissionTimer == nil {
            functionKeyPermissionTimer = Timer.scheduledTimer(withTimeInterval: 2, repeats: true) { [weak self] _ in
                self?.tryCreateFunctionKeyEventTap()
                self?.refreshFunctionKeyStatus()
            }
        }
        refreshFunctionKeyStatus()
    }

    private func installFunctionKeyMonitorsIfNeeded() {
        guard functionKeyGlobalMonitor == nil else { return }
        let mask: NSEvent.EventTypeMask = [.flagsChanged, .keyDown, .keyUp]
        functionKeyGlobalMonitor = NSEvent.addGlobalMonitorForEvents(matching: mask) { [weak self] event in
            self?.handleFunctionKeyNSEvent(event)
        }
        functionKeyLocalMonitor = NSEvent.addLocalMonitorForEvents(matching: mask) { [weak self] event in
            self?.handleFunctionKeyNSEvent(event)
            return event
        }
    }

    private func tryCreateFunctionKeyEventTap() {
        if let functionKeyEventTap, CGEvent.tapIsEnabled(tap: functionKeyEventTap) {
            return
        }
        let mask = CGEventMask(1 << CGEventType.flagsChanged.rawValue)
            | CGEventMask(1 << CGEventType.keyDown.rawValue)
            | CGEventMask(1 << CGEventType.keyUp.rawValue)
        let userData = UnsafeMutableRawPointer(Unmanaged.passUnretained(self).toOpaque())
        guard let tap = CGEvent.tapCreate(
            tap: .cgSessionEventTap,
            place: .headInsertEventTap,
            options: .defaultTap,
            eventsOfInterest: mask,
            callback: { _, type, event, userData in
                guard let userData else { return Unmanaged.passUnretained(event) }
                let delegate = Unmanaged<AppDelegate>.fromOpaque(userData).takeUnretainedValue()
                if type == .tapDisabledByTimeout || type == .tapDisabledByUserInput {
                    if let tap = delegate.functionKeyEventTap {
                        CGEvent.tapEnable(tap: tap, enable: true)
                    }
                    return Unmanaged.passUnretained(event)
                }
                if event.getIntegerValueField(.eventSourceUserData) == meyaInjectedEventTag {
                    return Unmanaged.passUnretained(event)
                }
                let shouldSuppress: Bool
                if type == .keyDown || type == .keyUp {
                    guard event.getIntegerValueField(.keyboardEventKeycode) == AppDelegate.functionHardwareKeyCode else {
                        if type == .keyDown {
                            delegate.cancelFunctionKeyVoiceForChord()
                        }
                        return Unmanaged.passUnretained(event)
                    }
                    shouldSuppress = delegate.handleFunctionKeyTransition(isDown: type == .keyDown, canConsumeEvent: true)
                } else if type == .flagsChanged {
                    let keyCode = event.getIntegerValueField(.keyboardEventKeycode)
                    if keyCode != AppDelegate.functionHardwareKeyCode {
                        if event.flags.contains(.maskSecondaryFn) {
                            delegate.cancelFunctionKeyVoiceForChord()
                        }
                        return Unmanaged.passUnretained(event)
                    }
                    shouldSuppress = delegate.handleFunctionKeyTransition(
                        isDown: event.flags.contains(.maskSecondaryFn),
                        canConsumeEvent: true
                    )
                } else {
                    return Unmanaged.passUnretained(event)
                }
                return shouldSuppress ? nil : Unmanaged.passUnretained(event)
            },
            userInfo: userData
        ) else { return }

        if let functionKeyEventTapSource {
            CFRunLoopRemoveSource(CFRunLoopGetMain(), functionKeyEventTapSource, .commonModes)
        }
        if let functionKeyEventTap {
            CFMachPortInvalidate(functionKeyEventTap)
        }
        functionKeyEventTap = tap
        functionKeyEventTapSource = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, tap, 0)
        if let functionKeyEventTapSource {
            CFRunLoopAddSource(CFRunLoopGetMain(), functionKeyEventTapSource, .commonModes)
        }
        CGEvent.tapEnable(tap: tap, enable: true)
        NSLog("麦芽 Meya Fn 语音已启用：长按录音，松开识别")
    }

    private func refreshFunctionKeyStatus() {
        let hasInputMonitoring = CGPreflightListenEventAccess()
        let hasAccessibility = AXIsProcessTrusted()
        let tapEnabled = functionKeyEventTap.map { CGEvent.tapIsEnabled(tap: $0) } ?? false
        let state: String
        if tapEnabled {
            functionKeyStatusItem?.title = "麦芽 Meya Fn 语音：已启用（长按录音）"
            state = "event_tap_enabled"
        } else if hasInputMonitoring || hasAccessibility {
            functionKeyStatusItem?.title = "Fn 备用监听已开：长按录音（短按仍交给系统）"
            state = "monitor_enabled"
        } else {
            functionKeyStatusItem?.title = "Fn 不可用：系统权限未落到当前进程"
            state = "waiting_for_permissions"
        }
        writeFunctionKeyDiagnostic(
            state: state,
            inputMonitoring: hasInputMonitoring,
            accessibility: hasAccessibility,
            tapEnabled: tapEnabled,
            monitorEnabled: functionKeyGlobalMonitor != nil
        )
    }

    private func writeFunctionKeyDiagnostic(
        state: String,
        inputMonitoring: Bool? = nil,
        accessibility: Bool? = nil,
        tapEnabled: Bool? = nil,
        monitorEnabled: Bool? = nil
    ) {
        let directory = projectDirectory.appendingPathComponent("runtime", isDirectory: true)
        let file = directory.appendingPathComponent("fn-status.json")
        var payload: [String: Any] = [
            "state": state,
            "bundleVersion": Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String ?? "unknown",
            "bundlePath": Bundle.main.bundlePath,
            "updatedAt": ISO8601DateFormatter().string(from: Date()),
        ]
        if let inputMonitoring { payload["inputMonitoring"] = inputMonitoring }
        if let accessibility { payload["accessibility"] = accessibility }
        if let tapEnabled { payload["tapEnabled"] = tapEnabled }
        if let monitorEnabled { payload["monitorEnabled"] = monitorEnabled }
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            let data = try JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys])
            try data.write(to: file, options: .atomic)
        } catch {
            NSLog("无法写入 Fn 自检状态：%@", error.localizedDescription)
        }
    }

    fileprivate func handleInputMethodModifierEvent(_ event: NSEvent) -> Bool {
        guard let isDown = functionKeyIsDown(in: event) else { return false }
        return handleFunctionKeyTransition(isDown: isDown, canConsumeEvent: true)
    }

    private func handleFunctionKeyNSEvent(_ event: NSEvent) {
        guard let isDown = functionKeyIsDown(in: event) else { return }
        _ = handleFunctionKeyTransition(isDown: isDown)
    }

    private func functionKeyIsDown(in event: NSEvent) -> Bool? {
        if event.type == .keyDown || event.type == .keyUp {
            guard event.keyCode == UInt16(AppDelegate.functionHardwareKeyCode) else { return nil }
            return event.type == .keyDown
        }
        if event.type == .flagsChanged {
            return event.modifierFlags.contains(.function)
        }
        return nil
    }

    private func handleFunctionKeyTransition(isDown: Bool, canConsumeEvent: Bool = false) -> Bool {
        guard isDown != isFunctionKeyDown else {
            return canConsumeEvent && ownsFunctionKeyGesture
        }
        isFunctionKeyDown = isDown

        if isDown {
            ownsFunctionKeyGesture = canConsumeEvent
            functionKeyChorded = false
            guard !isRecording, !isFinalizing else { return ownsFunctionKeyGesture }
            functionKeyHoldTriggered = false
            functionKeyHoldWorkItem?.cancel()
            let workItem = DispatchWorkItem { [weak self] in
                guard let self,
                      self.isFunctionKeyDown,
                      !self.functionKeyChorded,
                      !self.isRecording,
                      !self.isFinalizing
                else { return }
                self.functionKeyHoldTriggered = true
                self.requestMicrophoneAndStart()
            }
            functionKeyHoldWorkItem = workItem
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.28, execute: workItem)
            return ownsFunctionKeyGesture
        }

        functionKeyHoldWorkItem?.cancel()
        functionKeyHoldWorkItem = nil
        let shouldConsume = canConsumeEvent && ownsFunctionKeyGesture
        functionKeyHoldTriggered = false
        if isRecording && !functionKeyChorded {
            finishRecording()
        }
        ownsFunctionKeyGesture = false
        functionKeyChorded = false
        return shouldConsume
    }

    private func cancelFunctionKeyVoiceForChord() {
        guard isFunctionKeyDown else { return }
        functionKeyChorded = true
        functionKeyHoldWorkItem?.cancel()
        functionKeyHoldWorkItem = nil
        guard isRecording else { return }

        partialTimer?.invalidate()
        partialTimer = nil
        _ = audioCapture.stop()
        isRecording = false
        activeSession = UUID()
        partialQueued = false
        liveDraftInserter.cancel()
        recordingInputController = nil
        resetRollingWindow()
        setStatusIcon(description: "麦芽 Meya")
        overlay.hide()
        NSLog("已取消 Fn 语音：检测到组合键")
    }

    fileprivate func activateInputController(_ controller: LocalVoiceInputController) {
        activeInputController = controller
    }

    fileprivate func deactivateInputController(_ controller: LocalVoiceInputController) {
        if activeInputController === controller {
            activeInputController = nil
        }
    }

    private func resetRollingWindow() {
        committedText = ""
        committedEnd = 0
        lastHypothesis = ""
        draftRevision = 0
        partialQueued = false
        partialInFlight = false
    }

    private func requestMicrophoneAndStart() {
        switch AVCaptureDevice.authorizationStatus(for: .audio) {
        case .authorized:
            guard isFunctionKeyDown else { return }
            startRecording()
        case .notDetermined:
            AVCaptureDevice.requestAccess(for: .audio) { [weak self] granted in
                DispatchQueue.main.async {
                    if granted {
                        guard self?.isFunctionKeyDown == true else { return }
                        self?.startRecording()
                    } else {
                        self?.showPermissionError("请在“系统设置 → 隐私与安全性 → 麦克风”中允许麦芽 Meya。")
                    }
                }
            }
        default:
            showPermissionError("请在“系统设置 → 隐私与安全性 → 麦克风”中允许麦芽 Meya。")
        }
    }

    private func startRecording() {
        guard asrReady else {
            overlay.show(status: "识别服务未就绪", text: modelStatusText)
            DispatchQueue.main.asyncAfter(deadline: .now() + 3) { [weak self] in self?.overlay.hide() }
            return
        }
        do {
            submitPendingFeedback()
            let frontmostApplication = NSWorkspace.shared.frontmostApplication
            recordingAppName = frontmostApplication?.localizedName ?? ""
            recordingAppBundle = frontmostApplication?.bundleIdentifier ?? ""
            try audioCapture.start()
            activeSession = UUID()
            recordingInputController = activeInputController
            resetRollingWindow()
            liveDraftInserter.begin()
            recordingContextText = liveDraftInserter.contextText
            isRecording = true
            setStatusIcon(description: "麦芽 Meya 正在录音")
            overlay.showRecording()
            let session = activeSession
            partialTimer = Timer.scheduledTimer(withTimeInterval: LivePreview.partialPollInterval, repeats: true) { [weak self] _ in
                self?.requestPartialTranscription()
            }
            DispatchQueue.main.asyncAfter(deadline: .now() + LivePreview.firstPartialDelay) { [weak self] in
                guard let self, self.isRecording, self.activeSession == session else { return }
                self.requestPartialTranscription()
            }
        } catch {
            showPermissionError("录音启动失败：\(error.localizedDescription)")
        }
    }

    private func requestPartialTranscription() {
        guard isRecording, audioCapture.sampleCount >= LivePreview.minPartialSamples else { return }
        if partialInFlight {
            partialQueued = true
            return
        }
        guard let previewService else { return }
        let duration = Double(audioCapture.sampleCount) / RollingWindow.sampleRate
        let window = RollingWindow.bounds(duration: duration, committedEnd: committedEnd)
        let samples = audioCapture.snapshotWindow(from: window.start)
        guard samples.count >= LivePreview.minPartialSamples else { return }

        partialInFlight = true
        partialQueued = false
        draftRevision += 1
        let revision = draftRevision
        let session = activeSession
        let url = temporaryAudioURL(session: session, suffix: "partial")
        do {
            try WaveFile.write(samples: samples, to: url)
        } catch {
            partialInFlight = false
            return
        }

        previewService.transcribe(
            audioURL: url,
            final: false,
            windowStart: window.start,
            committedText: committedText,
            committedEnd: committedEnd,
            lastHypothesis: lastHypothesis,
            revision: revision,
            language: "zh"
        ) { [weak self] result in
            try? FileManager.default.removeItem(at: url)
            guard let self else { return }
            self.partialInFlight = false
            guard self.isRecording, self.activeSession == session else { return }
            if case .success(let response) = result, (response.revision ?? revision) >= self.draftRevision - 1 {
                self.committedText = response.committedText ?? self.committedText
                if let committedEnd = response.committedEnd {
                    self.committedEnd = committedEnd
                }
                self.lastHypothesis = response.lastHypothesis ?? self.lastHypothesis
                let preview = response.text?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                if !preview.isEmpty {
                    if self.liveDraftInserter.update(preview) {
                        self.overlay.update(status: "输入中 · 松开 Fn 定稿")
                    } else {
                        self.overlay.update(status: "输入中 · 浮层预览")
                    }
                }
            } else if case .failure(let error) = result {
                NSLog("临时识别失败: %@", error.localizedDescription)
            }
            if self.isRecording, self.partialQueued {
                self.requestPartialTranscription()
            }
        }
    }

    private func finishRecording() {
        partialTimer?.invalidate()
        partialTimer = nil
        let samples = audioCapture.stop()
        isRecording = false
        isFinalizing = true
        setStatusIcon(description: "麦芽 Meya 正在整理文字")
        overlay.showRecognizing()

        guard samples.count >= 8_000 else {
            completeFinal(text: "", error: "语音太短，未进行识别")
            return
        }

        let duration = Double(samples.count) / RollingWindow.sampleRate
        let rerunFull = RollingWindow.shouldRerunFull(duration: duration, committedEnd: committedEnd)
        let window = RollingWindow.bounds(duration: duration, committedEnd: committedEnd)
        let url = finalAudioURL()
        do {
            try WaveFile.write(samples: samples, to: url)
        } catch {
            completeFinal(text: "", error: "保存录音失败：\(error.localizedDescription)")
            return
        }

        var decodeURL = url
        if !rerunFull {
            let startIndex = min(samples.count, max(0, Int((window.start * RollingWindow.sampleRate).rounded())))
            decodeURL = temporaryAudioURL(session: activeSession, suffix: "final")
            do {
                try WaveFile.write(samples: Array(samples[startIndex...]), to: decodeURL)
            } catch {
                decodeURL = url
            }
        }

        let service = (finalModelReady ? refineService : nil) ?? previewService
        guard let service else {
            completeFinal(text: "", error: "识别服务未就绪")
            return
        }
        let decodePath = decodeURL
        let usedWindow = decodePath != url
        service.transcribe(
            audioURL: decodePath,
            final: true,
            windowStart: usedWindow ? window.start : nil,
            committedText: usedWindow ? committedText : nil,
            committedEnd: usedWindow ? committedEnd : nil,
            lastHypothesis: usedWindow ? lastHypothesis : nil,
            contextText: recordingContextText,
            draftText: lastHypothesis,
            appName: recordingAppName,
            appBundle: recordingAppBundle
        ) { [weak self] result in
            if decodePath != url {
                try? FileManager.default.removeItem(at: decodePath)
            }
            guard let self else { return }
            switch result {
            case .success(let response):
                self.completeFinal(
                    text: response.text ?? "",
                    error: nil,
                    response: response,
                    audioURL: url
                )
            case .failure(let error):
                self.completeFinal(text: "", error: error.localizedDescription)
            }
        }
    }

    private func completeFinal(
        text: String,
        error: String?,
        response: ASRResponse? = nil,
        audioURL: URL? = nil
    ) {
        isFinalizing = false
        setStatusIcon(description: "麦芽 Meya")

        if let error {
            liveDraftInserter.cancel()
            recordingInputController = nil
            overlay.show(status: "识别失败", text: error)
            DispatchQueue.main.asyncAfter(deadline: .now() + 4) { [weak self] in self?.overlay.hide() }
            return
        }

        let finalText = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !finalText.isEmpty else {
            liveDraftInserter.cancel()
            recordingInputController = nil
            overlay.show(status: "未检测到明显语音", text: "请重试")
            DispatchQueue.main.asyncAfter(deadline: .now() + 2) { [weak self] in self?.overlay.hide() }
            return
        }

        overlay.showResult()
        // Capture the observation before any final insertion path can reset the
        // live-draft state. This also covers InputMethodKit and clipboard/event
        // fallbacks used by Electron and web-based editors.
        liveDraftInserter.prepareFeedback(finalText: finalText)
        let inserted: Bool
        if liveDraftInserter.commit(finalText) {
            inserted = true
        } else if let inputController = recordingInputController ?? activeInputController {
            inputController.commitFinalText(finalText)
            inserted = true
        } else {
            inserted = TextInserter.insert(finalText)
        }
        if let response, let audioURL {
            liveDraftInserter.attachRecognition(
                rawText: response.rawText ?? "",
                finalText: finalText,
                audioPath: audioURL.path,
                appName: recordingAppName
            )
        }
        // Try immediately and once more after Electron has processed the
        // posted Unicode event. A captured baseline makes later edits fully
        // automatic even though opening the status menu changes app focus.
        liveDraftInserter.captureFeedbackBaseline()
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.35) { [weak self] in
            self?.liveDraftInserter.captureFeedbackBaseline()
        }
        recordingInputController = nil
        if !inserted {
            overlay.update(status: "已复制到剪贴板；请允许辅助功能后粘贴")
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + (inserted ? 0.8 : 5.0)) { [weak self] in
            self?.overlay.hide()
        }
    }

    @discardableResult
    private func submitPendingFeedback(explicit: Bool = false) -> Bool {
        guard let feedback = liveDraftInserter.automaticFeedbackSubmission(
            requireModification: explicit
        ) else { return false }
        return submitFeedback(feedback, explicit: explicit)
    }

    @discardableResult
    private func submitFeedback(_ feedback: FeedbackSubmission, explicit: Bool) -> Bool {
        guard let service = previewService else { return false }
        service.submitFeedback(
            expectedText: feedback.expectedText,
            editedText: feedback.editedText,
            rawText: feedback.rawText,
            finalText: feedback.finalText,
            audioPath: feedback.audioPath,
            appName: feedback.appName,
            explicit: explicit
        ) { [weak self] result in
            switch result {
            case .success(let response):
                let foundMapping = !(response.activated ?? []).isEmpty
                    || !(response.observed ?? []).isEmpty
                // No mapping means no learning happened. Preserve the
                // observation so the user can correct it and retry.
                if !explicit || foundMapping || response.acceptedUnchanged == true {
                    self?.liveDraftInserter.clearPendingFeedback(
                        observationID: feedback.observationID
                    )
                }
                if explicit {
                    self?.showFeedbackResult(response)
                }
            case .failure(let error):
                NSLog("本地纠正反馈记录失败: %@", error.localizedDescription)
                if explicit {
                    self?.overlay.show(status: "学习失败", text: error.localizedDescription)
                    DispatchQueue.main.asyncAfter(deadline: .now() + 3) { [weak self] in
                        self?.overlay.hide()
                    }
                }
            }
        }
        return true
    }

    @objc private func learnLastCorrection() {
        if submitPendingFeedback(explicit: true) {
            return
        }
        guard liveDraftInserter.hasPendingFeedback else {
            overlay.show(status: "暂无可学习的修改", text: "先完成一次语音输入并修改结果，再点击这里")
            DispatchQueue.main.asyncAfter(deadline: .now() + 2.5) { [weak self] in
                self?.overlay.hide()
            }
            return
        }
        showManualLearningDialog()
    }

    private func showManualLearningDialog() {
        guard let texts = liveDraftInserter.feedbackDialogTexts() else { return }
        let alert = NSAlert()
        alert.alertStyle = .informational
        alert.messageText = "对照学习上一句"
        alert.informativeText = "上面是麦芽插入的原文，请在下面把错误部分改成正确写法。新术语会自动加入个人词库。"
        alert.addButton(withTitle: "学习")
        alert.addButton(withTitle: "取消")

        let accessory = NSView(frame: NSRect(x: 0, y: 0, width: 440, height: 214))
        let originalLabel = NSTextField(labelWithString: "识别原文（只读）")
        originalLabel.frame = NSRect(x: 0, y: 190, width: 440, height: 18)
        accessory.addSubview(originalLabel)

        let originalScroll = NSScrollView(frame: NSRect(x: 0, y: 112, width: 440, height: 74))
        originalScroll.hasVerticalScroller = true
        originalScroll.borderType = .bezelBorder
        let originalEditor = NSTextView(frame: originalScroll.bounds)
        originalEditor.isRichText = false
        originalEditor.isEditable = false
        originalEditor.font = .systemFont(ofSize: 13)
        originalEditor.string = texts.recognized
        originalEditor.textContainerInset = NSSize(width: 6, height: 6)
        originalScroll.documentView = originalEditor
        accessory.addSubview(originalScroll)

        let correctedLabel = NSTextField(labelWithString: "正确文本（请修改）")
        correctedLabel.frame = NSRect(x: 0, y: 88, width: 440, height: 18)
        accessory.addSubview(correctedLabel)

        let correctedScroll = NSScrollView(frame: NSRect(x: 0, y: 8, width: 440, height: 76))
        correctedScroll.hasVerticalScroller = true
        correctedScroll.borderType = .bezelBorder
        let correctedEditor = NSTextView(frame: correctedScroll.bounds)
        correctedEditor.isRichText = false
        correctedEditor.font = .systemFont(ofSize: 13)
        correctedEditor.string = texts.corrected
        correctedEditor.textContainerInset = NSSize(width: 6, height: 6)
        correctedScroll.documentView = correctedEditor
        accessory.addSubview(correctedScroll)
        alert.accessoryView = accessory

        NSApp.activate(ignoringOtherApps: true)
        alert.window.initialFirstResponder = correctedEditor
        correctedEditor.selectAll(nil)
        guard alert.runModal() == .alertFirstButtonReturn else { return }
        guard let feedback = liveDraftInserter.manualFeedbackSubmission(
            originalText: originalEditor.string,
            correctedText: correctedEditor.string
        ) else {
            overlay.show(status: "没有检测到修改", text: "请在「正确文本」中改动错误部分，再点击学习")
            DispatchQueue.main.asyncAfter(deadline: .now() + 2.5) { [weak self] in
                self?.overlay.hide()
            }
            return
        }
        if !submitFeedback(feedback, explicit: true) {
            overlay.show(status: "学习服务未就绪", text: "请稍后重试，刚才的记录仍然保留")
            DispatchQueue.main.asyncAfter(deadline: .now() + 3) { [weak self] in
                self?.overlay.hide()
            }
        }
    }

    private func showFeedbackResult(_ response: ASRResponse) {
        let activated = response.activated ?? []
        let observed = response.observed ?? []
        if let learned = activated.first ?? observed.first {
            let status = activated.isEmpty ? "已确认这个说法" : "已学习刚才的修改"
            overlay.show(status: status, text: "\(learned.observed) → \(learned.canonical)")
        } else {
            overlay.show(
                status: "还没有提取出替换词",
                text: "请重试并只改动识别错误的部分；刚才的记录已保留"
            )
        }
        DispatchQueue.main.asyncAfter(deadline: .now() + 3) { [weak self] in
            self?.overlay.hide()
        }
    }

    private func showPermissionError(_ message: String) {
        overlay.show(status: "需要系统权限", text: message)
        DispatchQueue.main.asyncAfter(deadline: .now() + 6) { [weak self] in self?.overlay.hide() }
    }

    private func temporaryAudioURL(session: UUID, suffix: String) -> URL {
        projectDirectory
            .appendingPathComponent("recordings/live", isDirectory: true)
            .appendingPathComponent("\(session.uuidString)-\(suffix)-\(UUID().uuidString).wav")
    }

    private func finalAudioURL() -> URL {
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyyMMdd-HHmmss"
        return projectDirectory
            .appendingPathComponent("recordings/voice-input", isDirectory: true)
            .appendingPathComponent("\(formatter.string(from: Date())).wav")
    }

    @objc private func openTerms() {
        if keywordLibraryController == nil {
            keywordLibraryController = KeywordLibraryController(projectDirectory: projectDirectory)
        }
        keywordLibraryController?.show()
    }

    @objc private func openModelManager() {
        if modelManagerController == nil {
            modelManagerController = ModelManagerController(projectDirectory: projectDirectory) { [weak self] selection in
                self?.switchModels(to: selection)
            }
        }
        modelManagerController?.show()
        refreshModelStatus()
    }

    private func switchModels(to selection: ModelSelection) {
        guard !isRecording, !isFinalizing else {
            modelManagerController?.showError("请先结束当前语音输入")
            return
        }
        previewService?.stop()
        refineService?.stop()
        startASRServices(selection: selection)
    }

    private func refreshModelStatus() {
        let previewName = previewModelName.isEmpty ? "加载中…" : ModelConfigurationStore.shortName(previewModelName)
        let finalName: String
        if finalModelName.isEmpty {
            finalName = "加载中…"
        } else if !finalModelReady {
            finalName = "\(ModelConfigurationStore.shortName(finalModelName))（加载中）"
        } else {
            finalName = ModelConfigurationStore.shortName(finalModelName)
        }
        modelStatusText = "实时识别：\(previewName)；最终识别：\(finalName)"
        modelManagerController?.showRoles(
            preview: previewModelName,
            final: finalModelName,
            finalReady: finalModelReady
        )
    }

    private func startASRServices(selection: ModelSelection) {
        previewService?.stop()
        refineService?.stop()
        previewService = nil
        refineService = nil
        asrReady = false
        finalModelReady = false
        previewModelName = ""
        finalModelName = selection.final
        refreshModelStatus()
        setStatusIcon(description: "麦芽 Meya 正在加载模型")

        startWorker(role: "preview", model: selection.preview)
        if selection.preview != selection.final {
            startWorker(role: "final", model: selection.final)
        }
    }

    private func startWorker(role: String, model: String) {
        let service = ASRService(projectDirectory: projectDirectory, model: model, role: role)
        if role == "preview" {
            previewService = service
        } else {
            refineService = service
        }
        service.onReady = { [weak self, weak service] loadedModel in
            guard let self, let service else { return }
            if role == "preview", self.previewService === service {
                self.asrReady = true
                self.previewModelName = loadedModel
                self.setStatusIcon(description: "麦芽 Meya")
                if self.refineService == nil {
                    self.finalModelReady = true
                    self.finalModelName = loadedModel
                }
            } else if role == "final", self.refineService === service {
                self.finalModelReady = true
                self.finalModelName = loadedModel
            } else {
                return
            }
            self.refreshModelStatus()
        }
        service.onFatal = { [weak self, weak service] message in
            guard let self, let service else { return }
            if role == "preview", self.previewService === service {
                self.asrReady = false
                self.modelStatusText = "实时识别模型错误：\(message)"
                self.modelManagerController?.showError(message)
                self.overlay.show(status: "模型加载失败", text: message)
            } else if role == "final", self.refineService === service {
                self.finalModelReady = false
                self.refineService = nil
                NSLog("定稿模型失败，松手将沿用预览: %@", message)
                self.refreshModelStatus()
            }
        }
        do {
            try service.start()
        } catch {
            if role == "preview" {
                asrReady = false
                modelStatusText = "实时识别模型启动失败：\(error.localizedDescription)"
                modelManagerController?.showError(error.localizedDescription)
                overlay.show(status: "识别服务未启动", text: error.localizedDescription)
            } else {
                refineService = nil
                NSLog("定稿服务启动失败: %@", error.localizedDescription)
            }
        }
    }

    @objc private func openRecordings() {
        let directory = projectDirectory.appendingPathComponent("recordings/voice-input", isDirectory: true)
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        NSWorkspace.shared.open(directory)
    }

    @objc private func quit() {
        NSApp.terminate(nil)
    }
}

@main
private enum LocalVoiceInputMain {
    private static var inputMethodServer: IMKServer?

    static func main() {
        let app = NSApplication.shared
        if CommandLine.arguments.count == 3,
           CommandLine.arguments[1] == "--render-avatar-preview" {
            let outputDirectory = URL(fileURLWithPath: CommandLine.arguments[2], isDirectory: true)
            do {
                try FileManager.default.createDirectory(at: outputDirectory, withIntermediateDirectories: true)
                let avatar = Maya3DAvatarView(frame: NSRect(x: 0, y: 0, width: 180, height: 180))
                avatar.reset()
                avatar.update(levels: [0.15, 0.36, 0.72, 0.95, 0.62, 0.31, 0.18])
                try avatar.renderPreview(to: outputDirectory.appendingPathComponent("01-listening.png"))
                avatar.startProcessing()
                try avatar.renderPreview(to: outputDirectory.appendingPathComponent("02-processing.png"))
                avatar.showComplete()
                try avatar.renderPreview(to: outputDirectory.appendingPathComponent("03-complete.png"))
            } catch {
                fputs("preview failed: \(error.localizedDescription)\n", stderr)
                exit(1)
            }
            return
        }
        let delegate = AppDelegate()
        app.delegate = delegate
        app.setActivationPolicy(.accessory)
        let connectionName = Bundle.main.object(forInfoDictionaryKey: "InputMethodConnectionName") as? String
            ?? "LocalVoiceInput_Connection"
        inputMethodServer = IMKServer(
            name: connectionName,
            bundleIdentifier: Bundle.main.bundleIdentifier ?? "com.dp.inputmethod.LocalVoiceInput"
        )
        app.run()
    }
}
